import type {Lesson,Table,Question} from '../curriculum';
export const italianUnits=[
{title:'Sounds & first conversations',level:'Foundations',description:'The alphabet, vowels, spelling patterns, stress, and greetings.'},
{title:'People & places',level:'Beginner',description:'Essential verbs, noun gender, articles, plurals, and descriptions.'},
{title:'Everyday Italian',level:'Beginner',description:'Present-tense families, questions, routines, numbers, and prepositions.'},
{title:'Telling a story',level:'Developing',description:'Completed events, background, earlier events, and future plans.'},
{title:'Families and Communities',level:'AP theme 1',description:'Possession, relationships, pronouns, relatives, and community participation.'},
{title:'Language and Culture',level:'AP theme 2',description:'Registers, identity, regional diversity, and the subjunctive.'},
{title:'Art and Creativity',level:'AP theme 3',description:'Music, interpretation, conditionals, and cultural perspectives.'},
{title:'Science and Technology',level:'AP theme 4',description:'Innovation, evidence, passive voice, and communicating data.'},
{title:'Contemporary Life',level:'AP theme 5',description:'Education, work, public space, reported speech, and argument.'},
{title:'Global Contexts',level:'AP theme 6',description:'Environment, mobility, source evaluation, synthesis, and research presentation.'}
];
type Example=[string,string,string];
type Quiz=[string,string,string,string,string];
const raw:Lesson[]=[];
export const italianExamples:Record<number,Example[]>={};
const T=(caption:string,headers:string[],rows:string[][],note?:string):Table=>({caption,headers,rows,note});
const persons=['io','tu','lui / lei / Lei','noi','voi','loro'];
const V=(caption:string,names:string[],forms:string[][])=>T(caption,['Subject',...names],persons.map((p,i)=>[p,...forms.map(f=>f[i])]));
function L(title:string,desc:string,rule:string,first:Example,second:Example,story:[string,string],words:[string,string][],checks:Quiz[],speak:string,tables:Table[]){
 const index=raw.length; const questions:Question[]=checks.map(([prompt,correct,a,b,explanation],i)=>{const shift=(index+i)%3;const opts=[correct,a,b];return {prompt,options:[...opts.slice(shift),...opts.slice(0,shift)],answer:(3-shift)%3,explanation};});
 italianExamples[index+1]=[first,second];
 raw.push({id:`it-${index+1}`,slug:`${String(index+1).padStart(2,'0')}-${title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`,title,desc,unit:Math.floor(index/6),rule,example:first[0],translation:first[1],reading:story[0],english:story[1],words,questions,speak,tables});
}
// Chapter 1 — Roma
L('The Italian alphabet','Read the 21 core letters and recognize letters used in borrowed words.',
'Italian has 21 traditional alphabet letters. J, k, w, x, and y also occur in borrowed words and names. Letter names are different from sounds inside a word: the letter c is named ci, but its sound changes with the following vowel. Treat a spelling group such as ch as a pattern, not two English sounds added together.\n\nAccents are written on stressed final vowels in words such as città, caffè, and perché. The mark is part of the spelling. H is silent but changes c/g in spelling groups and distinguishes forms such as a (to/at) and ha (has). The next lessons isolate vowels and consonants before adding grammatical endings.',
['Una casa.','A house.','C before a is hard /k/.'],['La città.','The city.','Final à carries the stress; do not omit the accent.'],
['Roma. Sofia. Luca. Giulia. Una mappa. Un quaderno. Italia.','Rome. Sofia. Luca. Giulia. A map. A notebook. Italy.'],
[['casa','house'],['città','city'],['mappa','map'],['quaderno','notebook']],
[['Which letter is normally silent?','h','m','r','H is silent, although it has important spelling functions.'],['Which spelling correctly marks final stress?','città','citta','cìtta','Città has a written accent on the final stressed vowel.'],['In which city does the story begin?','Roma','Milano','Napoli','The first word is Roma: Rome.']],
'Read the character names and the four objects. Spell your name using Italian letter names.',
[T('Letters and English sound comparisons',['Letter','Usual sound','English equivalent (approx.)','Example'],[['a','/a/','a in father, kept steady','casa'],['b','/b/','b in book','bene'],['c','/k/ or /tʃ/','c in cat; ch in cheese before e/i','casa; cena'],['d','/d/','d in dog, tongue nearer the teeth','dove'],['e','/e/ or /ɛ/','e in bed; the closed sound is slightly higher','bene; caffè'],['f','/f/','f in fish','fare'],['g','/g/ or /dʒ/','g in go; j in jam before e/i','gatto; giro'],['h','silent','No sound by itself','ho'],['i','/i/ or /j/','ee in see; y in yes in some groups','vino; ieri'],['l','/l/','Clear l in leaf','luna'],['m','/m/','m in mother','mano'],['n','/n/','n in name','nome'],['o','/o/ or /ɔ/','Start of o in go, or aw in some accents; no glide','sole; cosa'],['p','/p/','p in spin, with little puff of air','pane'],['q','usually /kw/','qu in quick','quattro'],['r','/r/ or /ɾ/','A tap, sometimes like American butter; not the usual English r','Roma'],['s','/s/ or /z/','s in sun or z in zoo; varies by word/region','sale; rosa'],['t','/t/','t in stop, tongue nearer the teeth','tavolo'],['u','/u/ or /w/','oo in moon; w in we in some groups','luna; uomo'],['v','/v/','v in very','vino'],['z','/ts/ or /dz/','ts in cats or ds in adds, joined as one sound','pizza; zero']],'English comparisons are approximate and accent-dependent. Borrowed letters j/k/w/x/y retain word-specific pronunciations.')]);
L('Vowels and open sounds','Keep vowels steady and distinguish open and closed e/o.',
'Italian a, i, and u are relatively steady vowels: a as in father, i roughly like ee in see, u roughly like oo in moon. Avoid turning a vowel into an English-style glide. Even unstressed vowels are usually pronounced clearly rather than all becoming an “uh.” Practice casa, vino, and luna one syllable at a time.\n\nStressed e and o can be open or closed: /ɛ/ versus /e/, /ɔ/ versus /o/. English bed approximates open e; closed e is made with the tongue slightly higher. For closed o, round the lips and hold the start of English go without its glide. The distribution varies regionally, so learn model words instead of assuming every written e or o sounds identical.',
['Sofia ha una mappa.','Sofia has a map.','Keep the final a vowels clear.'],['Un caffè, per favore.','A coffee, please.','The final è is an open stressed vowel.'],
['Sofia ha una mappa. Luca ha una foto. Giulia ha un quaderno. Roma è sulla mappa.','Sofia has a map. Luca has a photo. Giulia has a notebook. Rome is on the map.'],
[['vino','wine'],['luna','moon'],['foto','photo'],['caffè','coffee']],
[['Which English word gives a rough model for Italian i?','see','sit','say','Italian /i/ is roughly the steady vowel in see, not the short vowel in sit.'],['What is important about unstressed Italian vowels?','Usually keep them clear.','Always reduce them to uh.','Always leave them silent.','Italian normally preserves recognizable unstressed vowels.'],['Who has the notebook?','Giulia','Sofia','Luca','Giulia ha un quaderno.']],
'Read casa, vino, luna, bene, and caffè. Record yourself and check for unwanted glides.',
[T('Vowel placement',['Sound','Mouth position','English equivalent (approx.)','Examples'],[['a /a/','Open jaw, low tongue','a in father','casa, mappa'],['i /i/','High front tongue, unrounded','ee in see, without a long glide','vino, amico'],['u /u/','High back tongue, rounded lips','oo in moon','luna, uno'],['e /e/','Mid-high front tongue','e in bed with a slightly higher tongue','perché'],['è /ɛ/','Mid-low front tongue','e in bed','caffè'],['o /o/','Mid-high back, rounded','Start of o in go, no w glide','sole'],['ò /ɔ/','Mid-low back, rounded','aw in law in some accents','però']],'Accent marks do not label every open/closed vowel in ordinary spelling.')]);
L('C, g, ch, gh, sc, gn, and gli','Decode Italian consonant groups with English comparisons.',
'C before a/o/u is /k/, while ce/ci is /tʃ/ like ch in cheese. G before a/o/u is hard /g/, while ge/gi is /dʒ/ like j in jam. Insert h to retain a hard sound before e/i: che, chi, ghe, ghi. In many cia/cio/ciu and gia/gio/giu words, i is a spelling signal rather than a separate ee syllable: ciao, giorno.\n\nSc before e/i is /ʃ/ like sh in ship; sch keeps /sk/. Gn is /ɲ/, somewhat like ny in canyon but produced as a single consonant. Gli often represents a palatal lateral /ʎ/, with no exact usual English equivalent; the tongue contacts the palate more broadly than English l. Some words, such as glicine, retain a hard gl group. Learn complete examples.',
['Ciao, Giulia!','Hello, Giulia!','Ciao begins with /tʃ/; Giulia begins with /dʒ/.'],['Chi ha la chiave?','Who has the key?','Ch keeps the /k/ sound before i.'],
['Giulia cerca una chiave. Luca ha la chiave. Sofia dice: «Ciao, Giulia!» Sul quaderno c’è una foto di una piazza.','Giulia is looking for a key. Luca has the key. Sofia says, “Hi, Giulia!” There is a photo of a square on the notebook.'],
[['chiave','key'],['piazza','square'],['giorno','day'],['bagno','bathroom']],
[['Which word starts with a hard /k/?','chiave','ciao','cena','Ch before i/e keeps c hard.'],['Which spelling is roughly like ny in canyon?','gn','gh','sc before e','Gn is one palatal nasal; English ny is only an approximation.'],['Who has the key?','Luca','Giulia','Sofia','Luca ha la chiave.']],
'Compare casa–cena, gatto–giro, chi–ci, and scuola–scena. Repeat bagno and famiglia using a single connected consonant group.',
[T('Consonant groups',['Spelling','IPA','English equivalent (approx.)','Examples'],[['c + a/o/u','/k/','c in cat','casa, cosa'],['ce / ci','/tʃ/','ch in cheese','cena, cinema'],['che / chi','/k/','k in skin','che, chiave'],['g + a/o/u','/g/','g in go','gatto, gusto'],['ge / gi','/dʒ/','j in jam','gelato, giro'],['ghe / ghi','/g/','g in give','spaghetti, laghi'],['sce / sci','/ʃ/','sh in ship','scena, scimmia'],['sche / schi','/sk/','sk in ski','schema, schiena'],['gn','/ɲ/','ny in canyon, joined more closely','bagno, sogno'],['gli','usually /ʎ/','No exact equivalent; approximate lli in million with the tongue against the palate','famiglia, figlio']])]);
L('Double consonants','Hear and produce the length contrast in non-English-like consonants.',
'Doubled consonants are held longer and can change meaning. Compare pala (shovel) with palla (ball), or sete (thirst) with sette (seven). For a stop such as tt, hold the closure slightly longer before releasing it. Do not insert a vowel between the two written consonants.\n\nFor continuous consonants such as ll or nn, sustain the contact or airflow: palla, anno. English compounds such as bookcase or unnamed can help you notice a boundary with prolonged articulation, but Italian doubles operate inside a word. Consonant length and vowel stress are different features. Read the whole word at a natural pace after practicing the contrast.',
['Ho sette biglietti.','I have seven tickets.','Sette and biglietti both contain a doubled t.'],['La palla è piccola.','The ball is small.','Hold ll and cc without adding a separate vowel.'],
['Luca ha sette biglietti, ma gli amici sono tre. Sofia ride. «Tre biglietti, Luca!» Giulia scrive sette e tre sul quaderno.','Luca has seven tickets, but there are three friends. Sofia laughs. “Three tickets, Luca!” Giulia writes seven and three in the notebook.'],
[['biglietto','ticket'],['sette','seven'],['palla','ball'],['anno','year']],
[['Which spelling means seven?','sette','sete','seta','Sette has a long /t/; sete means thirst.'],['How should a doubled stop be produced?','Hold the closure longer, then release.','Add an extra uh vowel.','Ignore one letter.','Lengthen the consonant itself; do not create another syllable.'],['How many friends are traveling?','Three','Seven','Two','Gli amici sono tre.']],
'Alternate pala–palla, sete–sette, and nono–nonno. Read Ho sette biglietti without slowing every syllable equally.',
[T('Length contrasts',['Single','Double','English aid / technique'],[['pala — shovel','palla — ball','Keep the tongue contact longer for ll'],['sete — thirst','sette — seven','Hold the t closure; no extra vowel'],['nono — ninth','nonno — grandfather','Sustain the n contact'],['caro — dear / expensive','carro — cart','Extend the tap/trill rather than using English r']])]);
L('Stress, accents, and connected speech','Mark the stressed syllable and read short phrases naturally.',
'Italian stress often falls on the next-to-last syllable, but many words differ: ca-SA is not the model for casa, which is CA-sa. Compare CA-sa, a-MI-co, cit-TÀ, and te-LE-fo-no. Capitals here are teaching annotations, not normal spelling. Final stressed vowels normally take an accent mark.\n\nSmall words connect to neighboring words in speech. Do not pause between every article and noun: una mappa is one phrase. A written apostrophe can indicate elision: l’amico. È means is; e means and. The accent makes a grammatical difference as well as signaling pronunciation. Practice the complete phrase after identifying each stressed syllable.',
['Roma è grande e bella.','Rome is large and beautiful.','È is the verb; e connects two adjectives.'],['Un amico, un’amica.','A male friend, a female friend.','The apostrophe occurs in feminine un’amica, not masculine un amico.'],
['Roma è grande e bella. Sofia guarda la mappa. Luca guarda una foto. Giulia scrive: «Una città, tre amici, un viaggio».','Rome is large and beautiful. Sofia looks at the map. Luca looks at a photo. Giulia writes: “One city, three friends, one journey.”'],
[['amico','male friend'],['amica','female friend'],['viaggio','journey'],['bello','beautiful']],
[['Which word means “is”?','è','e','ed','È with an accent is a form of essere; e means and.'],['Where does amico carry stress?','a-MI-co','A-mi-co','a-mi-CO','The penultimate syllable mi is stressed.'],['What does Giulia write about?','A city, three friends, and a journey','A closed museum','A missing suitcase','She writes Una città, tre amici, un viaggio.']],
'Read the passage in phrases, then mark stress in Roma, amico, viaggio, telefono, and città.',
[T('Stress and spelling',['Word / phrase','Annotation','Meaning','Notice'],[['casa','CA-sa','house','Penultimate stress'],['amico','a-MI-co','male friend','Penultimate stress'],['telefono','te-LE-fo-no','telephone','Antepenultimate stress'],['città','cit-TÀ','city','Final accent is written'],['perché','per-CHÉ','why / because','Acute accent on closed é'],['è / e','/ɛ/ / /e/','is / and','Keep the spelling distinction']])]);
L('Greetings and introductions','Choose tu or Lei and introduce the three travelers.',
'Ciao is informal and can mean hello or goodbye. Buongiorno and buonasera are useful polite greetings; buonanotte normally signals a farewell before sleep. Arrivederci is a general goodbye. Mi chiamo Sofia introduces a name; come ti chiami? asks informally. Learn these as full expressions before studying reflexives.\n\nLei is polite singular you and takes third-person singular verbs: Come si chiama? Tu takes second-person singular: come ti chiami? Do not confuse polite Lei with voi, plural you. Piacere is a natural short expression when meeting someone. In Italy, levels of formality depend on relationship and setting rather than a universal age rule.',
['Mi chiamo Sofia. Piacere!','My name is Sofia. Nice to meet you!','Mi chiamo is a complete introductory expression.'],['Buongiorno, come si chiama?','Hello, what is your name?','Si with third-person chiama is a polite singular address.'],
['— Ciao! Mi chiamo Sofia.\n— Piacere, sono Luca.\n— Io sono Giulia. Questo è il nostro quaderno.\n— Un quaderno per il viaggio?\n— Sì: luoghi, parole e voci.','— Hi! My name is Sofia.\n— Nice to meet you, I am Luca.\n— I am Giulia. This is our notebook.\n— A notebook for the journey?\n— Yes: places, words, and voices.'],
[['buongiorno','good day / hello'],['piacere','pleased to meet you'],['voce','voice'],['parola','word']],
[['Which form asks a name politely?','Come si chiama?','Come ti chiami?','Come vi chiamate?','Lei uses third-person singular si chiama.'],['When is buonanotte usually appropriate?','A farewell before sleep','Every daytime arrival','Only when ordering lunch','Buonanotte is a good-night farewell rather than the standard evening arrival greeting.'],['What will the notebook collect?','Places, words, and voices','Only ticket prices','Only family names','Giulia names luoghi, parole e voci.']],
'Introduce yourself to a classmate and then to a guesthouse owner. Keep tu and Lei forms consistent.',
[T('Introductions by register',['Function','Informal singular','Polite singular','Plural'],[['Ask name','Come ti chiami?','Come si chiama?','Come vi chiamate?'],['Greet','Ciao!','Buongiorno!','Buongiorno!'],['Say thanks','Grazie!','Grazie!','Grazie!'],['Say goodbye','Ciao!','Arrivederci!','Arrivederci!']])]);
// Chapter 2 — Bologna
L('Essere and subject pronouns','Build identities, descriptions, and locations with to be.',
'Italian subject pronouns are io, tu, lui/lei, noi, voi, loro. The present of essere is sono, sei, è, siamo, siete, sono. Subjects are often omitted because the verb and context identify them: Sono Sofia. Use an explicit pronoun for contrast or clarification, particularly because sono can mean I am or they are.\n\nEssere introduces identity, origin, location, and descriptions: Sono studentessa; sono di Roma; siamo a Bologna; il quaderno è nuovo. Polite Lei takes è, not sei. Adjectives after essere agree with the subject: Sofia è stanca; gli amici sono stanchi. Do not add a separate “do” auxiliary when turning a statement into a question.',
['Siamo a Bologna.','We are in Bologna.','Noi can be omitted; siamo already marks we.'],['Tu sei stanco; lei è stanca.','You are tired; she is tired.','The verb agrees with person and the adjective with gender/number.'],
['Sofia è studentessa. Luca è fotografo. Giulia è una loro amica. Ora sono a Bologna. La stazione è grande. Il quaderno è nella borsa di Giulia. «Siamo qui», dice Sofia.','Sofia is a student. Luca is a photographer. Giulia is a friend of theirs. Now they are in Bologna. The station is large. The notebook is in Giulia’s bag. “We are here,” Sofia says.'],
[['stazione','station'],['studente','student'],['stanco','tired'],['qui','here']],
[['Complete: Noi ___ a Bologna.','siamo','sono','siete','Noi requires siamo.'],['Which form agrees with polite Lei?','è','sei','siete','Polite singular Lei takes third-person singular è.'],['Where is the notebook?','In Giulia’s bag','On the train','At home','Il quaderno è nella borsa di Giulia.']],
'Introduce yourself, give your city of origin, and say where you are now. Describe the friends using plural forms.',
[V('Essere — present',['essere'],[['sono','sei','è','siamo','siete','sono']]),T('Subject and meaning',['Subject','English','Example'],[['io / tu','I / you','Io sono; tu sei'],['lui / lei / Lei','he / she / polite you','Lei è qui.'],['noi / voi / loro','we / you / they','Noi siamo; voi siete; loro sono']])]);
L('Avere: possession, age, and sensations','Use ho, hai, ha, abbiamo, avete, and hanno.',
'Avere means to have: ho, hai, ha, abbiamo, avete, hanno. The h in ho/hai/ha/hanno is silent but essential in writing. Contrast ha (has) with a (to/at), and ho (I have) with o (or). Possession uses an object: Ho una mappa.\n\nItalian expresses age and several sensations with avere rather than essere: Ho vent’anni; ho fame; ho sete; ho freddo. Think of these as conventional phrases, not literal English-to-Italian replacements. The verb changes with the experiencer: abbiamo fame, we have hunger → we are hungry. Numbers receive a dedicated lesson; first learn the construction.',
['Ho fame e ho sete.','I am hungry and thirsty.','Italian uses avere for these sensations.'],['Giulia ha vent’anni.','Giulia is twenty years old.','Age uses avere; ha keeps the silent h.'],
['A Bologna, gli amici hanno una camera vicino al centro. Sofia ha una mappa, Luca ha una macchina fotografica e Giulia ha il quaderno. Dopo il viaggio hanno fame. «Abbiamo anche sete», dice Luca. Sul tavolo c’è acqua.','In Bologna, the friends have a room near the center. Sofia has a map, Luca has a camera, and Giulia has the notebook. After the journey they are hungry. “We are thirsty too,” Luca says. There is water on the table.'],
[['fame','hunger'],['sete','thirst'],['acqua','water'],['camera','room']],
[['Complete: Loro ___ sete.','hanno','ha','avete','Loro takes hanno.'],['Which sentence correctly expresses age?','Ho vent’anni.','Sono vent’anni.','Faccio venti anni is always the basic neutral equivalent','Avere expresses how old a person is.'],['What do the friends need after the journey?','Food and water','A new camera','A new train','Hanno fame and hanno sete express hunger and thirst.']],
'Say what you have in your bag, how old you are, and whether you are hungry, thirsty, hot, or cold.',
[V('Avere — present',['avere'],[['ho','hai','ha','abbiamo','avete','hanno']]),T('Avere expressions',['Italian','English'],[['avere fame / sete','to be hungry / thirsty'],['avere caldo / freddo','to feel hot / cold'],['avere paura','to be afraid'],['avere vent’anni','to be twenty years old']])]);
L('Noun gender and indefinite articles','Choose un, uno, una, and un’ from the following noun.',
'Italian nouns are normally masculine or feminine. Many -o nouns are masculine and many -a nouns feminine, but endings are clues rather than guarantees: il problema is masculine, la mano is feminine. Nouns in -e can belong to either gender. Learn each noun with its article.\n\nUse un for most masculine singular nouns, including before vowels: un libro, un amico. Use uno before z, s + consonant, and certain other consonant groups: uno zaino, uno studente. Feminine una becomes un’ before a vowel: una casa, un’amica. The apostrophe distinguishes un’amica from masculine un amico; do not add it to every un before a vowel.',
['Un amico e un’amica.','A male friend and a female friend.','Only the feminine elided article takes the apostrophe.'],['Uno studente ha uno zaino.','A student has a backpack.','S + consonant and z require uno in these masculine nouns.'],
['Nella camera di Bologna ci sono un tavolo e una sedia. Luca ha uno zaino. Sofia incontra un amico; Giulia incontra un’amica. Una guida mostra loro un libro con una mappa dei portici. Nel quaderno compare una nuova parola: incontro.','In the Bologna room there are a table and a chair. Luca has a backpack. Sofia meets a male friend; Giulia meets a female friend. A guide shows them a book with a map of the porticoes. A new word appears in the notebook: meeting.'],
[['zaino','backpack'],['sedia','chair'],['incontro','meeting'],['libro','book']],
[['Choose the article: ___ studente.','uno','una','un’','Masculine studente begins with s + consonant, so use uno.'],['Which masculine phrase needs no apostrophe?','un amico','un’amico','uno amico','Un before a masculine vowel-initial noun has no apostrophe.'],['What does the guide show them?','A book with a map','A concert ticket','An empty bag','Una guida mostra loro un libro con una mappa.']],
'Name six objects and people with indefinite articles. Include a masculine vowel-initial noun and a feminine one.',
[T('Indefinite articles',['Noun type','Article','Examples'],[['Most masculine consonants','un','un libro, un tavolo'],['Masculine vowel','un','un amico'],['Masculine z / s + consonant','uno','uno zaino, uno studente'],['Feminine consonant','una','una casa'],['Feminine vowel','un’','un’amica, un’isola']])]);
L('Plural nouns','Change -o, -a, and -e nouns and recognize invariant words.',
'Most masculine -o nouns form their plural in -i: libro → libri. Most feminine -a nouns take -e: casa → case. Many nouns ending in -e use -i regardless of gender: studente → studenti, stazione → stazioni. Gender stays with the noun even when the singular and plural share an ending with another gender.\n\nSome nouns do not change: città, caffè, and many borrowed nouns such as bar. Their articles and adjectives still show number. Spelling can preserve a hard consonant: amica → amiche. Other plurals change the sound: amico → amici. Learn these pairs with the noun, rather than inserting h automatically into every plural.',
['Due libri e tre case.','Two books and three houses.','-o → -i; feminine -a → -e.'],['Un’amica, due amiche.','One female friend, two female friends.','H keeps /k/ before the plural e.'],
['Giulia prepara la pagina di Bologna. Sul tavolo ci sono due libri, tre mappe e alcune foto. Sofia scrive i nomi delle strade. Luca sceglie due immagini dei portici. Le foto non raccontano tutto: nel quaderno servono anche le parole delle persone incontrate.','Giulia prepares the Bologna page. On the table are two books, three maps, and some photos. Sofia writes street names. Luca chooses two images of the porticoes. Photos do not tell everything: the notebook also needs the words of the people they met.'],
[['strada','street'],['portico','portico / covered arcade'],['persona','person'],['immagine','image']],
[['What is the plural of stazione?','stazioni','stazione','staziones','Nouns in -e commonly take -i: stazione → stazioni.'],['Which noun normally stays unchanged in the plural?','città','libro','casa','Accented final-vowel nouns such as città are invariant.'],['What does Luca choose?','Two images of the porticoes','Three maps','Two train tickets','Luca sceglie due immagini dei portici.']],
'Make a plural inventory for the shared travel notebook. Include invariant città and foto.',
[T('Plural patterns',['Type','Singular','Plural','Note'],[['Masculine -o','libro','libri','-o → -i'],['Feminine -a','casa','case','-a → -e'],['Noun in -e','stazione','stazioni','-e → -i'],['Hard consonant preserved','amica','amiche','-ca → -che'],['Sound changes','amico','amici','-co → -ci here'],['Final accented vowel','città','città','Invariant'],['Shortened feminine noun','foto','foto','Invariant; from fotografia']])]);
L('Definite articles','Select il, lo, l’, la, i, gli, and le.',
'Definite articles identify a known or specific noun. Masculine singular il becomes plural i; lo and masculine l’ become gli. Use lo before z, s + consonant, gn, ps, and related groups, and l’ before a vowel. Feminine la and l’ both become le in the plural.\n\nChoose the article by the immediately following sound when an adjective intervenes: lo studente but il bravo studente. Italian often uses definite articles with general categories: Mi piace la musica. An article is not simply a word-for-word replacement for English the. Personal names, possessives, and geographical names have additional patterns introduced later.',
['Gli amici sono qui.','The friends are here.','Masculine vowel-initial amico uses l’amico → gli amici.'],['Il bravo studente legge.','The good student reads.','Bravo changes the immediately following sound after the article.'],
['La guida incontra gli amici davanti alla libreria. Il libro sul tavolo parla dei portici. Lo zaino di Luca è sotto la sedia. Le mappe sono aperte. Prima di lasciare Bologna, Giulia scrive i nomi delle persone che hanno aiutato il gruppo.','The guide meets the friends outside the bookshop. The book on the table discusses the porticoes. Luca’s backpack is under the chair. The maps are open. Before leaving Bologna, Giulia writes the names of the people who helped the group.'],
[['guida','guide'],['libreria','bookshop'],['gruppo','group'],['musica','music']],
[['Choose the plural of lo studente.','gli studenti','i studenti','le studenti','Lo forms its masculine plural with gli.'],['Why is il correct in il bravo studente?','The following sound is b in bravo.','Studente is feminine.','All adjectives require il.','The article reflects the sound immediately following it.'],['Where is Luca’s backpack?','Under the chair','On the table','Outside the library','Lo zaino di Luca è sotto la sedia.']],
'Describe the room using definite articles. Change each masculine singular phrase to plural.',
[T('Definite article chart',['Noun opening','Masculine singular','Masculine plural','Examples'],[['Most consonants','il','i','il libro → i libri'],['Vowel','l’','gli','l’amico → gli amici'],['s + consonant, z, gn, ps…','lo','gli','lo studente → gli studenti']]),T('Feminine articles',['Noun opening','Singular','Plural','Examples'],[['Consonant','la','le','la casa → le case'],['Vowel','l’','le','l’amica → le amiche']])]);
L('Adjectives and agreement','Describe people and things across gender and number.',
'Many Italian adjectives have four forms: nuovo, nuova, nuovi, nuove. They agree with the noun, not with the person describing it. Adjectives ending in -e commonly have one singular and one plural form: interessante → interessanti. A mixed-gender group conventionally takes masculine plural agreement.\n\nMany adjectives follow the noun, especially when distinguishing it: un libro italiano. Others can precede it, sometimes changing emphasis or meaning: un vecchio amico is a longtime friend, un amico vecchio an elderly friend. Start with clear noun–adjective pairs, and keep agreement after essere as well: le case sono belle.',
['Le case sono belle.','The houses are beautiful.','Belle is feminine plural to match case.'],['Un libro interessante, due libri interessanti.','One interesting book, two interesting books.','Adjectives in -e commonly form plural -i.'],
['L’ultima pagina di Bologna è pronta. Le strade sono lunghe, i portici sono alti e le persone incontrate sono gentili. Sofia ha una mappa nuova. Luca guarda le foto migliori e Giulia chiude il quaderno. La prossima città è Firenze: gli amici vogliono descriverla con parole più precise.','The last Bologna page is ready. The streets are long, the porticoes are tall, and the people they met are kind. Sofia has a new map. Luca looks at the best photos and Giulia closes the notebook. The next city is Florence: the friends want to describe it with more precise words.'],
[['nuovo','new'],['gentile','kind'],['alto','tall / high'],['pronto','ready']],
[['Complete: le mappe sono ___.','nuove','nuovo','nuovi','Mappe is feminine plural, so use nuove.'],['What can adjective position affect?','Emphasis or meaning','Only punctuation','Nothing in every case','Vecchio amico and amico vecchio illustrate a possible difference of meaning.'],['Which city comes next?','Firenze','Roma','Genova','La prossima città è Firenze.']],
'Describe four people or objects, then change each phrase into the plural. Contrast vecchio amico and amico vecchio.',
[T('Adjective forms',['Adjective','Masc. singular','Fem. singular','Masc. plural','Fem. plural'],[['new','nuovo','nuova','nuovi','nuove'],['beautiful','bello','bella','belli','belle'],['tall','alto','alta','alti','alte'],['interesting','interessante','interessante','interessanti','interessanti'],['kind','gentile','gentile','gentili','gentili']])]);
// Chapter 3 — Firenze
L('Present tense: -are verbs','Conjugate parlare, visitare, and cercare.',
'Regular -are verbs use -o, -i, -a, -iamo, -ate, -ano. Remove -are and add the ending: parlo, parli, parla, parliamo, parlate, parlano. The present can express both current activity and a habit; Italian does not require a separate progressive form for every English “is doing.”\n\nSpelling preserves the stem sound in verbs such as cercare: cerco, cerchi, cerca, cerchiamo, cercate, cercano. The h before i prevents c from becoming /tʃ/. Verbs ending in -iare often combine written i patterns differently: studi, studiamo. Learn spelling changes together with the spoken form, not as a silent decoration.',
['Parliamo italiano.','We speak Italian.','-iamo identifies first-person plural.'],['Cerchi una mappa?','Are you looking for a map?','H preserves the hard c before i.'],
['A Firenze, Sofia cerca una stanza tranquilla per lavorare. Luca fotografa una piazza e Giulia parla con una libraia. Ogni sera gli amici preparano una pagina del quaderno. Non cercano soltanto monumenti: cercano anche le parole con cui le persone descrivono il proprio quartiere.','In Florence, Sofia looks for a quiet room to work. Luca photographs a square and Giulia talks to a bookseller. Each evening the friends prepare a notebook page. They seek not only monuments but also the words people use to describe their neighborhood.'],
[['parlare','to speak'],['cercare','to look for'],['quartiere','neighborhood'],['sera','evening']],
[['Complete: Voi ___ italiano.','parlate','parlano','parliamo','Voi uses -ate for regular -are verbs.'],['Choose the correct spelling for tu + cercare.','cerchi','cerci','cerca','Cerchi retains /k/ before i by inserting h.'],['Who speaks with the bookseller?','Giulia','Luca','Sofia','Giulia parla con una libraia.']],
'Describe a typical travel day with three -are verbs. Conjugate cercare with tu and noi.',
[V('Present -are verbs',['parlare','cercare'],[['parlo','parli','parla','parliamo','parlate','parlano'],['cerco','cerchi','cerca','cerchiamo','cercate','cercano']])]);
L('Present tense: -ere and -ire','Compare leggere, dormire, and the -isc- family.',
'Regular -ere verbs take -o, -i, -e, -iamo, -ete, -ono. Regular -ire verbs use -o, -i, -e, -iamo, -ite, -ono. Thus leggo/leggi/legge and dormo/dormi/dorme differ in their stems and plural voi forms. Learn the full infinitive with the pattern.\n\nSome -ire verbs insert -isc- in all singular persons and third-person plural: capisco, capisci, capisce, capiamo, capite, capiscono. Noi and voi lack the expansion. Capire and finire follow this family, but dormire does not. The sound of sc changes according to the following vowel just as in other words.',
['Capisco il testo.','I understand the text.','Capire inserts -isc- in this singular form.'],['Noi capiamo; voi capite.','We understand; you understand.','No -isc- in noi or voi.'],
['Giulia legge una pagina sulla storia di Firenze. Sofia capisce le idee principali, ma cerca alcune parole. Luca dorme per mezz’ora, poi legge le didascalie delle foto. Insieme scelgono una frase per il quaderno: capire un luogo richiede tempo e domande.','Giulia reads a page about Florence’s history. Sofia understands the main ideas but looks up some words. Luca sleeps for half an hour, then reads photo captions. Together they choose a sentence for the notebook: understanding a place takes time and questions.'],
[['leggere','to read'],['capire','to understand'],['dormire','to sleep'],['didascalia','caption']],
[['Complete: Loro ___ il testo.','capiscono','capiamo','capite','Third-person plural of capire is capiscono.'],['Which verb does not take the -isc- expansion?','dormire','capire','finire','Dormire has dormo, dormi, dorme without isc.'],['What does Luca read after resting?','Photo captions','A timetable','An email','Luca legge le didascalie delle foto.']],
'Explain what you read, what you understand, and what you finish each day. Use both singular and plural forms.',
[V('Present verb families',['leggere','dormire','capire'],[['leggo','leggi','legge','leggiamo','leggete','leggono'],['dormo','dormi','dorme','dormiamo','dormite','dormono'],['capisco','capisci','capisce','capiamo','capite','capiscono']])]);
L('Irregular presents and modal verbs','Use andare, fare, potere, volere, and dovere.',
'Frequent verbs have irregular stems. Andare gives vado, vai, va, andiamo, andate, vanno. Fare gives faccio, fai, fa, facciamo, fate, fanno. Learn these forms as whole patterns; an ending alone cannot reconstruct vado from andare.\n\nPotere, volere, and dovere are modal verbs followed by an infinitive: posso leggere, voglio partire, devo studiare. The second verb stays in its infinitive form. Differentiate ability or permission (potere), desire (volere), and obligation (dovere). In the present, a single modal can govern more than one coordinated infinitive: voglio leggere e scrivere.',
['Vogliamo visitare il museo.','We want to visit the museum.','Volere is conjugated; visitare remains infinitive.'],['Devo studiare, ma posso uscire dopo.','I have to study, but I can go out later.','Dovere expresses obligation; potere expresses possibility.'],
['Gli amici vanno verso il museo. Sofia vuole capire come si costruisce una mostra. Luca può fare fotografie soltanto dove è permesso. Giulia deve finire alcune domande prima dell’incontro con una guida. Vogliono aggiungere al quaderno non solo ciò che vedono, ma anche come imparano a guardare.','The friends head toward the museum. Sofia wants to understand how an exhibition is made. Luca can take photographs only where allowed. Giulia must finish some questions before meeting a guide. They want to add not only what they see to the notebook but also how they learn to look.'],
[['andare','to go'],['fare','to do / make'],['potere','to be able to / may'],['dovere','to have to']],
[['Complete: Noi ___ al museo.','andiamo','vanno','vado','Noi takes andiamo.'],['Which verb form follows voglio?','An infinitive','Always a past participle','A second conjugated present verb','A modal such as volere governs an infinitive: voglio leggere.'],['Who must finish some questions?','Giulia','Sofia','Luca','Giulia deve finire alcune domande.']],
'Plan a museum visit, saying what you want, can, and must do.',
[V('Frequent irregulars',['andare','fare','potere','volere','dovere'],[['vado','vai','va','andiamo','andate','vanno'],['faccio','fai','fa','facciamo','fate','fanno'],['posso','puoi','può','possiamo','potete','possono'],['voglio','vuoi','vuole','vogliamo','volete','vogliono'],['devo','devi','deve','dobbiamo','dovete','devono']])]);
L('Questions and negation','Ask specific questions and put non before the verb.',
'Yes/no questions can keep statement word order with question intonation: Hai una mappa? Do not insert an equivalent of English do. Question words include chi, che cosa/cosa, dove, quando, come, perché, and quale. Perché means either why or because; its function depends on the sentence.\n\nNon normally precedes the finite verb: Non capisco. With a modal, negate the modal: Non posso venire. Later, non also precedes unstressed object pronouns: non lo vedo. A negative word such as niente after the verb normally combines with non; this concord receives a dedicated later lesson. First practice simple complete statements and questions.',
['Perché non vieni?','Why are you not coming?','Question word followed by non and the finite verb.'],['Non posso venire.','I cannot come.','Non negates the conjugated modal posso.'],
['Davanti al museo, Luca non trova il biglietto. «Dove l’hai messo?» chiede Giulia. Sofia guarda la borsa e risponde: «È qui». Luca non vuole perdere tempo, ma Giulia ha una domanda: perché alcune fotografie possono essere scattate e altre no? Scrive la domanda per la guida, invece di indovinare la risposta.','Outside the museum, Luca cannot find his ticket. “Where did you put it?” Giulia asks. Sofia looks in the bag and replies, “It is here.” Luca does not want to waste time, but Giulia has a question: why are some photographs allowed and others not? She writes it for the guide instead of guessing.'],
[['dove','where'],['quando','when'],['perché','why / because'],['risposta','answer']],
[['Choose “Where are you going?”','Dove vai?','Quando vai?','Perché vai?','Dove asks about location or destination.'],['Negate posso venire.','Non posso venire.','Posso non is always the neutral equivalent','Posso venire non.','Non normally comes before the finite modal.'],['Why does Giulia record the photography question?','To ask the guide rather than guess','To buy another ticket','To leave the city','She writes it for the guide instead of inventing an answer.']],
'Ask five travel questions and answer two negatively. Distinguish perché as why from perché as because.',
[T('Questions and negatives',['Function','Italian','English'],[['Person','Chi viene?','Who is coming?'],['Thing','Che cosa leggi?','What are you reading?'],['Place','Dove vai?','Where are you going?'],['Time','Quando parti?','When do you leave?'],['Reason','Perché resti?','Why are you staying?'],['Negation','Non resto.','I am not staying.']])]);
L('Numbers, time, and prepositions','Count objects and express location, destination, and time.',
'Learn numbers as reusable groups: uno through dieci, undici through diciannove, then venti, trenta, quaranta. Ventuno and ventotto drop the final vowel of venti; ventitré carries a final accent. For clock time, use È l’una but Sono le due. An appointment at two is alle due.\n\nCommon prepositions include di, a, da, in, con, su, per, tra/fra. Cities usually take a: a Firenze. Countries generally take in: in Italia. A destination can use da when it identifies a person or professional: vado da Giulia, vado dal medico. Many prepositions combine with articles: a + il = al, di + la = della. Learn complete phrases, not just English glosses.',
['Ci vediamo alle due.','We will see each other at two.','A + le contracts to alle.'],['Siamo a Firenze, in Italia.','We are in Florence, in Italy.','City a; country in in these basic location expressions.'],
['La visita comincia alle dieci. Gli amici arrivano alle nove e mezza e aspettano davanti al museo. Dopo la visita vanno in una piccola libreria. Hanno ventitré fotografie da scegliere e due pagine da completare. Giulia scrive Firenze in alto; sotto, Sofia aggiunge il luogo e l’ora di ogni incontro.','The visit begins at ten. The friends arrive at nine thirty and wait outside the museum. Afterwards they go into a small bookshop. They have twenty-three photographs to choose and two pages to complete. Giulia writes Florence at the top; below it Sofia adds the location and time of each meeting.'],
[['ora','hour / time'],['alle dieci','at ten'],['mezza','half (feminine)'],['luogo','place']],
[['Choose “in Florence”.','a Firenze','in Firenze is the standard basic city pattern','da Firenze means in Florence','The usual basic city location uses a.'],['Choose “at two o’clock”.','alle due','sono le due','a due ora','Alle due is a time complement; sono le due states the time.'],['When do the friends arrive?','At nine thirty','At ten thirty','At two','Arrivano alle nove e mezza.']],
'Give directions to a meeting and name the time. Count three supplies and state a price above twenty.',
[T('Numbers and time',['Expression','Meaning','Pattern'],[['uno, due, tre, quattro, cinque','1–5','Uno shortens to un before many masculine nouns'],['sei, sette, otto, nove, dieci','6–10','Hold the doubles in sette and otto'],['ventuno / ventotto / ventitré','21 / 28 / 23','Elision and written final accent'],['È l’una. / Sono le due.','It is one. / It is two.','Singular vs plural'],['all’una / alle due','at one / at two','A + article']]),T('Articulated prepositions',['Base','il','lo','la','l’','i','gli','le'],[['di','del','dello','della','dell’','dei','degli','delle'],['a','al','allo','alla','all’','ai','agli','alle'],['da','dal','dallo','dalla','dall’','dai','dagli','dalle'],['in','nel','nello','nella','nell’','nei','negli','nelle'],['su','sul','sullo','sulla','sull’','sui','sugli','sulle']])]);
L('Reflexive verbs and daily routines','Use mi, ti, si, ci, vi, si with present-tense routines.',
'A reflexive verb uses an unstressed pronoun matching the subject: mi sveglio, ti svegli, si sveglia, ci svegliamo, vi svegliate, si svegliano. The pronoun normally precedes the finite present verb. Some verbs are reflexive in meaning, while others are learned as pronominal expressions: chiamarsi, sentirsi.\n\nWith an infinitive after a modal, the pronoun can attach to the infinitive or precede the modal: devo alzarmi / mi devo alzare. Drop the final e of the infinitive before attaching mi. Negation comes before the pronoun when it precedes the finite verb: non mi alzo. Do not confuse plural reciprocal action with a literal one-person reflexive meaning: ci incontriamo can mean we meet each other.',
['Mi sveglio alle sette.','I wake up at seven.','Mi agrees with the implied io subject.'],['Devo alzarmi presto.','I must get up early.','Attach mi to alzare after dropping its final e.'],
['Nell’ultima mattina a Firenze, Sofia si sveglia presto e prepara la mappa per Venezia. Luca si alza più tardi, mentre Giulia si mette vicino alla finestra per scrivere. Si incontrano all’ingresso con le borse pronte. Prima di uscire, controllano che il quaderno sia con loro: la prossima pagina avrà anche le voci della città sull’acqua.','On their last morning in Florence, Sofia wakes early and prepares the map for Venice. Luca gets up later, while Giulia sits by the window to write. They meet at the entrance with bags ready. Before leaving, they check that the notebook is with them: the next page will also have the voices of the city on the water.'],
[['svegliarsi','to wake up'],['alzarsi','to get up'],['presto','early'],['ingresso','entrance']],
[['Complete: Noi ___ svegliamo.','ci','si','mi','Noi takes reflexive ci.'],['Which is equivalent to mi devo alzare?','devo alzarmi','devo mi alzare','devo alzaremi','A clitic can attach to the modal’s infinitive after dropping its final e.'],['Where are they traveling next?','Venezia','Bologna','Torino','Sofia prepares the map for Venezia.']],
'Describe your morning, then retell it about two friends. Include a modal with an attached reflexive.',
[V('Svegliarsi — present',['reflexive + verb'],[['mi sveglio','ti svegli','si sveglia','ci svegliamo','vi svegliate','si svegliano']]),T('Two modal positions',['Before modal','Attached to infinitive'],[['Mi devo alzare.','Devo alzarmi.'],['Ci possiamo incontrare.','Possiamo incontrarci.'],['Non mi voglio fermare.','Non voglio fermarmi.']])]);
// Chapter 4 — Venezia
L('Passato prossimo with avere','Report completed past events with an auxiliary and participle.',
'The passato prossimo combines a present auxiliary with a past participle. With avere, use ho, hai, ha, abbiamo, avete, hanno: ho parlato, hai letto. Regular participles are -ato for -are, -uto for many -ere verbs, and -ito for -ire, but many common -ere verbs are irregular. The auxiliary identifies the subject.\n\nAn active participle with avere normally does not agree with the subject: Sofia ha parlato; gli amici hanno parlato. Do not use a conjugated present form after the auxiliary. Ho letto means I read / have read, depending on context; it is not restricted to English present-perfect situations. Time markers such as ieri anchor the event in the travel story.',
['Ieri ho parlato con una guida.','Yesterday I spoke with a guide.','Ho + participle presents a completed past event.'],['Abbiamo finito la pagina.','We finished the page.','The auxiliary changes with noi; finito stays unchanged.'],
['A Venezia, Giulia apre il quaderno e racconta il viaggio. Ieri hanno comprato i biglietti e hanno letto il programma. Sofia ha cercato la fermata giusta, mentre Luca ha fotografato le borse sul treno. Prima di dormire, hanno ascoltato una registrazione fatta a Firenze. Ora vogliono capire quali suoni distinguono la nuova città.','In Venice, Giulia opens the notebook and recounts the journey. Yesterday they bought tickets and read the schedule. Sofia looked for the right stop, while Luca photographed the bags on the train. Before sleeping, they listened to a recording made in Florence. Now they want to understand which sounds distinguish the new city.'],
[['ieri','yesterday'],['comprare','to buy'],['ascoltare','to listen'],['registrazione','recording']],
[['Complete: Noi ___ parlato.','abbiamo','hanno','siamo','With parlare, noi uses abbiamo + participle.'],['Which is the regular participle of finire?','finito','finisco','finire','The regular -ire participle ends in -ito.'],['Where was the earlier recording made?','Firenze','Venezia','Bologna','Una registrazione fatta a Firenze.']],
'Recount five completed travel activities using avere and a participle.',
[V('Passato prossimo with avere',['parlare'],[['ho parlato','hai parlato','ha parlato','abbiamo parlato','avete parlato','hanno parlato']]),T('Regular participles',['Infinitive ending','Example','Participle'],[['-are','parlare','parlato'],['-ere','ricevere','ricevuto'],['-ire','finire','finito']])]);
L('Passato prossimo with essere','Agree the participle in movement and reflexive constructions.',
'Many intransitive change-of-location or change-of-state verbs use essere: sono andato, è arrivata, siamo partiti. Reflexive verbs also use essere: mi sono svegliata. Do not assume every movement verb takes essere; camminare and viaggiare normally use avere. Learn a verb with its auxiliary and construction.\n\nWith essere, the participle agrees with the subject: Sofia è arrivata; Luca è arrivato; Sofia e Giulia sono arrivate; tutti sono arrivati. Some verbs change auxiliary with transitive use: ho finito il libro but il viaggio è finito. The table gives safe basic patterns rather than a universal meaning-based shortcut.',
['Sofia è arrivata a Venezia.','Sofia arrived in Venice.','Arrivata agrees with feminine singular Sofia.'],['Ci siamo svegliati presto.','We woke up early.','A reflexive uses essere and subject agreement.'],
['Sofia e Giulia sono arrivate alla fermata prima di Luca. Lui è rimasto vicino al ponte per fotografare l’acqua. Dopo l’incontro, gli amici sono andati alla pensione e si sono riposati. Non hanno viaggiato molto quel giorno, ma sono usciti la sera per ascoltare la città quando le strade erano più tranquille.','Sofia and Giulia reached the stop before Luca. He stayed near the bridge to photograph the water. After meeting, the friends went to the guesthouse and rested. They did not travel much that day, but went out in the evening to listen to the city when the streets were quieter.'],
[['arrivare','to arrive'],['partire','to leave'],['rimanere','to remain'],['ponte','bridge']],
[['Choose the correct sentence about Sofia and Giulia.','Sono arrivate.','Sono arrivato.','Hanno arrivate.','Essere and feminine plural participle agreement give sono arrivate.'],['Which verb normally uses avere?','viaggiare','arrivare','partire','Movement alone does not select essere; viaggiare normally uses avere.'],['Where did Luca remain?','Near the bridge','At the station','In the library','Lui è rimasto vicino al ponte.']],
'Retell your arrival using four essere verbs. Change the subject from one person to a group and adjust agreement.',
[T('Essere and participle agreement',['Subject','Arrival','Reflexive'],[['Luca','è arrivato','si è svegliato'],['Sofia','è arrivata','si è svegliata'],['Luca e Giulia','sono arrivati','si sono svegliati'],['Sofia e Giulia','sono arrivate','si sono svegliate']]),T('Auxiliary contrasts',['Avere','Essere'],[['ho viaggiato','sono arrivato/a'],['ho camminato','sono partito/a'],['ho finito il libro','il viaggio è finito']])]);
L('Irregular participles and sequencing','Link completed events using first, then, and finally.',
'Frequent participles must be learned: fare → fatto, dire → detto, leggere → letto, scrivere → scritto, vedere → visto, prendere → preso, mettere → messo, aprire → aperto. Knowing the infinitive ending is not enough to predict these forms. The auxiliary still changes with the subject.\n\nOrganize a narrative with prima, poi, dopo, and infine. Dopo + noun or infinitive has its own construction; a simple safe pattern is a completed clause after poi: Prima abbiamo letto, poi abbiamo scritto. Avoid mixing a timeline connector with an unexplained change of subject. These narrative tools will later support AP-style accounts and presentations.',
['Abbiamo letto e poi abbiamo scritto.','We read and then we wrote.','Letto and scritto are irregular participles.'],['Luca ha preso la mappa.','Luca took the map.','Prendere forms preso, not a regular invented prenduto.'],
['Prima di uscire, gli amici hanno letto un avviso vicino alla porta. Poi Sofia ha preso la mappa e Giulia ha scritto l’ora dell’incontro. Luca ha aperto la borsa e ha messo il telefono in una tasca sicura. Infine hanno chiesto alla proprietaria dove ascoltare una conversazione sulla vita del quartiere.','Before leaving, the friends read a notice near the door. Then Sofia took the map and Giulia wrote the meeting time. Luca opened his bag and put his phone in a secure pocket. Finally, they asked the owner where to hear a conversation about neighborhood life.'],
[['avviso','notice'],['scrivere','to write'],['prendere','to take'],['tasca','pocket']],
[['Choose the participle of scrivere.','scritto','scrivuto','scrive','Scritto is the irregular participle.'],['Which connector normally means finally?','infine','prima','mentre','Infine introduces a final step; prima comes first, mentre indicates while.'],['What did Giulia write?','The meeting time','A train price','A restaurant name','Giulia ha scritto l’ora dell’incontro.']],
'Recount a four-step visit with prima, poi, dopo, and infine. Include three irregular participles.',
[T('Irregular participles',['Infinitive','Participle','Example'],[['fare','fatto','ho fatto'],['dire','detto','ha detto'],['leggere','letto','abbiamo letto'],['scrivere','scritto','avete scritto'],['vedere','visto','hanno visto'],['prendere','preso','ho preso'],['mettere','messo','hai messo'],['aprire','aperto','ha aperto']])]);
L('Imperfetto: background and habits','Describe how things were and what people used to do.',
'The imperfetto presents ongoing, habitual, or backgrounded past activity. Forms have -vo, -vi, -va, -vamo, -vate, -vano after the appropriate vowel: parlavo, leggevo, dormivo. Essere is irregular: ero, eri, era, eravamo, eravate, erano. Io and lui/lei forms differ, unlike some other Romance languages.\n\nUse it for setting and past routines: Era sera; da piccola leggevo molto. The difference from passato prossimo is viewpoint, not an automatic long-versus-short rule. An action lasting hours can be presented as completed. First practice a coherent background scene, then add a completed interruption in the next lesson.',
['Da piccola leggevo ogni sera.','As a child I used to read every evening.','Imperfetto describes a repeated past habit.'],['Era sera e pioveva.','It was evening and it was raining.','Two background descriptions set a scene.'],
['Da piccola, Giulia veniva a Venezia con una zia. Guardava le barche e faceva domande sui nomi dei luoghi. Sua zia raccontava storie, ma Giulia non ricordava tutti i dettagli. Ora, mentre scrive nel quaderno, riconosce una sensazione familiare: ogni strada sembrava aprire un’altra domanda.','As a child, Giulia used to come to Venice with an aunt. She watched boats and asked about place names. Her aunt told stories, but Giulia did not remember every detail. Now, as she writes, she recognizes a familiar feeling: every street seemed to open another question.'],
[['zia','aunt'],['ricordo','memory'],['barca','boat'],['dettaglio','detail']],
[['Choose the imperfetto of noi + essere.','eravamo','erano','siamo stati','Eravamo is imperfect first-person plural.'],['What does the imperfect often supply?','Background or a past habit','Only a completed one-time result','Only future plans','The imperfect frames an activity as ongoing, backgrounded, or habitual.'],['Who visited Venice with Giulia in childhood?','Her aunt','Sofia','Luca','Giulia veniva a Venezia con una zia.']],
'Describe a childhood place using four imperfect verbs, then tell a friend how you used to spend time there.',
[V('Imperfetto',['parlare','leggere','dormire','essere'],[['parlavo','parlavi','parlava','parlavamo','parlavate','parlavano'],['leggevo','leggevi','leggeva','leggevamo','leggevate','leggevano'],['dormivo','dormivi','dormiva','dormivamo','dormivate','dormivano'],['ero','eri','era','eravamo','eravate','erano']])]);
L('Events against a background','Combine imperfect and completed past without losing the timeline.',
'Use imperfect for a scene in progress and passato prossimo for a completed event that enters it: Leggevo quando è arrivata Sofia. The reading is background; Sofia’s arrival advances the narrative. Mentre often introduces simultaneous ongoing activity: mentre leggevo, Luca scriveva.\n\nTense choice changes perspective. Ho lavorato tre ore presents a completed period; lavoravo al progetto leaves it ongoing or backgrounded. Repetition can also be bounded: ho visitato Venezia tre volte counts three completed visits. Before choosing a tense, ask what role the event plays in the story, not only how many minutes it lasted.',
['Leggevo quando è arrivata Sofia.','I was reading when Sofia arrived.','Imperfect background plus completed arrival.'],['Ho lavorato per tre ore.','I worked for three hours.','A long activity can be presented as completed.'],
['Pioveva e gli amici aspettavano sotto un portico. Luca controllava il telefono mentre Giulia leggeva un avviso. All’improvviso, una donna ha chiesto se cercavano l’incontro del quartiere. Sofia ha risposto di sì. La donna li ha accompagnati in una sala dove alcune persone stavano preparando una piccola discussione pubblica.','It was raining and the friends were waiting under a portico. Luca checked his phone while Giulia read a notice. Suddenly a woman asked if they were looking for the neighborhood meeting. Sofia said yes. The woman took them to a room where people were preparing a small public discussion.'],
[['pioggia','rain'],['aspettare','to wait'],['sala','room / hall'],['discussione','discussion']],
[['Which is the background in leggevo quando è arrivata Sofia?','leggevo','è arrivata','Sofia','Leggevo presents an ongoing activity; è arrivata adds a completed event.'],['Can a three-hour activity use passato prossimo?','Yes, if framed as a completed period','No, duration always requires imperfect','Only with a negative','Viewpoint matters more than raw duration.'],['Who helped the friends find the meeting?','A woman who approached them','A train conductor','A bookseller in Bologna','Una donna asked them and accompanied them to the room.']],
'Set a rainy travel scene with three imperfect verbs, then add two events that change it.',
[T('Narrative viewpoint',['Background','Completed event','Meaning'],[['Leggevo…','…quando è arrivata Sofia.','Reading was underway at the arrival'],['Pioveva…','…quando siamo usciti.','Rain provides the setting'],['Visitavo spesso Venezia.','Ho visitato Venezia tre volte.','Habit versus counted completed visits'],['Lavoravo al progetto.','Ho lavorato per tre ore.','Ongoing work versus completed duration']])]);
L('Future tense and plans','Form regular futures and learn common irregular stems.',
'The future endings are -ò, -ai, -à, -emo, -ete, -anno. Regular -are verbs change a to e: parlerò, parlerai. -Ere and -ire verbs use stems such as prender- and partir-. Final stress marks on -ò and -à are part of the spelling. All six forms belong in the paradigm.\n\nCommon stems are irregular: essere → sar-, avere → avr-, andare → andr-, fare → far-, venire → verr-, potere → potr-. The present can also describe a scheduled plan when time is clear: domani parto. In another context the future expresses a conjecture: sarà a casa, probably he/she is home. Learn the planning use first.',
['Domani andremo a Napoli.','Tomorrow we will go to Naples.','Andare uses the irregular future stem andr-.'],['Parleremo con una famiglia.','We will speak with a family.','-are becomes -er- before future endings.'],
['Dopo l’incontro a Venezia, gli amici preparano il viaggio verso Napoli. Porteranno il quaderno e qualche registrazione. A Napoli incontreranno una famiglia amica di Giulia. Sofia chiederà come cambia un quartiere nel tempo; Luca farà fotografie soltanto con il permesso delle persone. Giulia scriverà una nuova domanda: chi decide quali storie una comunità racconta?','After the Venice meeting, the friends prepare to travel to Naples. They will bring the notebook and a few recordings. In Naples they will meet a family Giulia knows. Sofia will ask how a neighborhood changes over time; Luca will photograph people only with permission. Giulia will write a new question: who decides which stories a community tells?'],
[['domani','tomorrow'],['famiglia','family'],['permesso','permission'],['comunità','community']],
[['Complete: Io ___ domani.','partirò','partirà','partiremo','First-person singular future ends in -ò.'],['Which is the future stem of essere?','sar-','esser-','er-','Essere has the irregular future stem sar-.'],['Where will the friends meet a family?','Napoli','Venezia','Torino','A Napoli incontreranno una famiglia amica di Giulia.']],
'Plan your next stop with four future verbs and explain one scheduled plan using a present tense.',
[V('Future paradigms',['parlare','partire','essere','andare'],[['parlerò','parlerai','parlerà','parleremo','parlerete','parleranno'],['partirò','partirai','partirà','partiremo','partirete','partiranno'],['sarò','sarai','sarà','saremo','sarete','saranno'],['andrò','andrai','andrà','andremo','andrete','andranno']])]);
// Chapter 5 — AP Families and Communities, Napoli
L('Possessives and family relationships','Agree possessives with what is owned and handle singular family terms.',
'Possessives agree with the thing possessed: il mio libro, la mia mappa, i miei libri, le mie mappe. The owner stays I in all four. Use tuo, suo, nostro, vostro, loro for other owners; loro remains unchanged. Articles usually accompany possessives.\n\nMany unmodified singular family nouns omit the article: mia madre, tuo fratello, suo padre. Plural family terms take it: i miei fratelli. Loro normally retains the article even with singular kinship: la loro madre. Modifiers and affectionate forms can restore an article. Describe the particular household in your source rather than assuming one family pattern represents all of Italy.',
['Mia madre vive a Napoli.','My mother lives in Naples.','An unmodified singular kinship term normally omits the article.'],['Le nostre mappe sono nuove.','Our maps are new.','Nostre agrees with feminine plural mappe.'],
['A Napoli, Giulia presenta Sofia e Luca a sua zia Elena. La loro casa è piccola, ma il tavolo della cucina accoglie tutti. Elena racconta che sua madre abitava nello stesso quartiere, mentre i suoi figli vivono altrove. Sofia annota le differenze tra le generazioni. Non vuole scrivere “la famiglia italiana è così”: questa è la storia di Elena, non un modello per tutte le famiglie.','In Naples, Giulia introduces Sofia and Luca to her aunt Elena. Their home is small, but the kitchen table seats everyone. Elena says her mother lived in the same neighborhood, while her children live elsewhere. Sofia notes the differences between generations. She does not want to write “the Italian family is like this”: this is Elena’s story, not a model for all families.'],
[['madre','mother'],['padre','father'],['fratello','brother'],['generazione','generation']],
[['Choose the usual unmodified singular phrase.','mia madre','la mia madre is always obligatory','mio madre','Mia agrees with madre; the article is normally omitted in this basic kinship phrase.'],['Complete: le ___ mappe.','nostre','nostri','nostro','Mappe is feminine plural, requiring nostre.'],['Why does Sofia avoid generalizing?','Elena’s household does not represent every family.','She cannot write Italian.','Elena refuses to speak.','The reading explicitly distinguishes one household from a national stereotype.']],
'Compare two households you know. Identify a specific practice and explain whose experience supports it.',
[T('Possessives',['Owner','Masc. singular','Fem. singular','Masc. plural','Fem. plural'],[['my','mio','mia','miei','mie'],['your','tuo','tua','tuoi','tue'],['his/her/polite your','suo','sua','suoi','sue'],['our','nostro','nostra','nostri','nostre'],['your plural','vostro','vostra','vostri','vostre'],['their','loro','loro','loro','loro']]),T('Family article patterns',['Basic singular','Plural / exception'],[['mia madre','le mie sorelle'],['tuo fratello','i tuoi fratelli'],['suo padre','il loro padre']])]);
L('Direct object pronouns','Replace people and things with mi, ti, lo, la, ci, vi, li, le.',
'A direct object is directly affected by the verb. Unstressed pronouns normally precede a finite verb: lo vedo, la conosco, li ascolto. Choose gender and number according to the object, not the speaker. La can also refer to polite singular you.\n\nWith an infinitive, attach the pronoun after dropping final e: voglio leggerlo; lo voglio leggere is another permitted modal pattern. In the passato prossimo with preceding lo/la/li/le, the participle agrees with the pronoun: l’ho vista, li ho letti. Begin with an explicit object, then replace it so the reference stays clear.',
['La conosco.','I know her.','La replaces a feminine singular direct object.'],['Le lettere? Le ho lette.','The letters? I read them.','Preceding le triggers feminine plural participle agreement.'],
['Elena mostra alcune lettere di famiglia. Giulia le legge con attenzione; Sofia le fotografa soltanto dopo aver chiesto il permesso. Luca cerca un nome in una foto: «Lo conosci?» Elena risponde che è suo nonno. Il gruppo decide di non pubblicare le lettere. Può descriverne il ruolo nella memoria familiare senza rendere pubbliche parole private.','Elena shows some family letters. Giulia reads them carefully; Sofia photographs them only after asking permission. Luca looks for a name in a photo: “Do you know him?” Elena says it is her grandfather. The group decides not to publish the letters. They can describe their role in family memory without making private words public.'],
[['lettera','letter'],['nonno','grandfather'],['memoria','memory'],['attenzione','attention']],
[['Which pronoun replaces feminine plural lettere?','le','li','lo','Le is feminine plural direct object.'],['Choose “I saw her” with a preceding direct object.','L’ho vista.','L’ho visto. always regardless of gender','La ho vedere.','La elides before ho, and the participle agrees: vista.'],['Will the friends publish the letters?','No','Yes, without asking','Only Luca will','Il gruppo decide di non pubblicare le lettere.']],
'Describe three objects, replace them with pronouns, then recount seeing or reading them in the past.',
[V('Direct object pronouns',['unstressed accusative'],[['mi','ti','lo / la','ci','vi','li / le']]),T('Objects in the past',['Object','Pronoun + past'],[['il libro','l’ho letto'],['la lettera','l’ho letta'],['i libri','li ho letti'],['le lettere','le ho lette']])]);
L('Indirect objects and piacere','Identify recipients and make the liked thing agree with piacere.',
'Indirect objects often answer to whom: do il libro a Giulia → le do il libro. Use mi, ti, gli/le, ci, vi, gli in common modern usage; loro after the verb is a more formal plural alternative. Distinguish gli (to him/them) from direct li (them, masculine).\n\nPiacere reverses the usual English viewpoint. Mi piace la musica literally means music is pleasing to me: la musica is the subject. Plural things take piacciono: mi piacciono le canzoni. A past form with essere agrees with the liked subject: mi è piaciuta la canzone. Keep recipient and grammatical subject separate.',
['Mi piacciono le canzoni.','I like the songs.','Plural canzoni takes piacciono.'],['Le do il quaderno.','I give her the notebook.','Le marks the recipient; quaderno is the direct object.'],
['Elena porta gli amici a un incontro del quartiere. A Luca piace la musica che arriva dalla sala, ma a Sofia piacciono soprattutto le conversazioni. Giulia dà il quaderno a Elena e le chiede di indicare una parola importante per la comunità. Elena scrive “vicinato”. Spiega loro che una rete di aiuto non si vede sempre nelle fotografie.','Elena takes the friends to a neighborhood meeting. Luca likes the music coming from the hall, but Sofia especially likes the conversations. Giulia gives Elena the notebook and asks her to name an important community word. Elena writes “neighborhood ties.” She explains that a support network is not always visible in photographs.'],
[['canzone','song'],['vicinato','neighborhood ties'],['aiuto','help'],['rete','network']],
[['Complete: Mi ___ le canzoni.','piacciono','piace','piaci','The grammatical subject is plural canzoni.'],['Which pronoun means to her?','le','la','li','Le is feminine singular indirect object; la is direct object.'],['Which word does Elena write?','vicinato','fotografia','treno','Elena scrive vicinato.']],
'Explain what three people like, mixing singular and plural subjects. Give an object to each person with an indirect pronoun.',
[V('Indirect object pronouns',['unstressed dative'],[['mi','ti','gli / le','ci','vi','gli (also formal loro after verb)']]),T('Piacere agreement',['Subject','Present','Completed past'],[['la canzone','mi piace','mi è piaciuta'],['il libro','mi piace','mi è piaciuto'],['le canzoni','mi piacciono','mi sono piaciute'],['i libri','mi piacciono','mi sono piaciuti']])]);
L('Combined pronouns','Order recipient and object in forms such as me lo and glielo.',
'When an indirect/reflexive clitic comes before a direct object clitic, mi/ti/ci/vi/si change to me/te/ce/ve/se: me lo dai, te la mostro. The recipient precedes the direct object. Gli and le combine with lo/la/li/le into one word: glielo, gliela, glieli, gliele.\n\nWith an infinitive the whole cluster can attach: voglio mostrarglielo. With preceding direct pronouns in the compound past, agreement still matters: gliel’ho data for a feminine singular object. Do not choose the direct pronoun according to the recipient’s gender. Expand the sentence back to explicit nouns if you lose track of who receives what.',
['Te lo mostro.','I show it to you.','Te identifies the recipient; lo identifies a masculine object.'],['La mappa? Gliel’ho data.','The map? I gave it to him/her.','Data agrees with feminine mappa, not with the recipient.'],
['Sofia vuole aggiungere al quaderno una copia della mappa del quartiere. Elena gliela mostra e spiega dove si svolgono le attività dei residenti. Luca chiede a Giulia una fotografia: lei gliela manda, ma ricorda che non tutte le immagini possono essere condivise. Nel quaderno annotano anche chi ha autorizzato ogni materiale, così una buona intenzione non diventa una pubblicazione senza consenso.','Sofia wants to add a copy of the neighborhood map. Elena shows it to her and explains where residents’ activities take place. Luca asks Giulia for a photograph: she sends it to him, but reminds him not every image may be shared. They record who authorized each item so a good intention does not become publication without consent.'],
[['consenso','consent'],['condividere','to share'],['residente','resident'],['copia','copy']],
[['Choose “I show it to you” for a masculine object.','Te lo mostro.','Ti lo mostro.','Lo te mostro.','Ti becomes te before the direct clitic lo.'],['What controls data in gliel’ho data?','The feminine singular direct object','Always the recipient','The speaker’s gender','The preceding direct-object component refers to a feminine singular item.'],['What extra information goes in the notebook?','Who authorized each material','Only the number of photos','The price of every letter','They note chi ha autorizzato ogni materiale.']],
'Ask a partner for a map, give them a photo, and recount the exchanges using combined pronouns.',
[T('Recipient + object',['Recipient','lo','la','li','le'],[['mi','me lo','me la','me li','me le'],['ti','te lo','te la','te li','te le'],['gli / le','glielo','gliela','glieli','gliele'],['ci','ce lo','ce la','ce li','ce le'],['vi','ve lo','ve la','ve li','ve le'],['si','se lo','se la','se li','se le']])]);
L('Relative clauses: che and cui','Connect descriptions of people and things without repeating nouns.',
'Che introduces a relative clause when it is subject or direct object: la donna che parla; la lettera che leggo. Unlike Romanian pe care, Italian does not normally add a second object clitic in la lettera che leggo. Keep the grammatical systems distinct.\n\nAfter a preposition use cui or an agreeing form of il quale: la persona con cui parlo, il quartiere in cui vivo. Possessive cui follows an article agreeing with the possessed noun: la donna il cui figlio canta. Cui itself is invariant. An isolated noun phrase does not tell you which relative form to use; identify its role inside the relative clause.',
['La persona con cui parlo è Elena.','The person I am speaking with is Elena.','Con requires cui in this relative construction.'],['Il libro che leggo è suo.','The book I am reading is hers/his.','Che is a direct object here; no extra lo is needed.'],
['Elena presenta una vicina che organizza il doposcuola. La sala in cui lavorano è piccola, ma le persone con cui collaborano vengono da strade diverse. Sofia ascolta la storia di una madre il cui figlio partecipa alle attività. Il gruppo capisce che una comunità non è soltanto un luogo: è fatta anche di relazioni che richiedono tempo e responsabilità.','Elena introduces a neighbor who organizes after-school activities. The room where they work is small, but their collaborators come from different streets. Sofia listens to a mother whose son takes part. The group understands that a community is not only a place: it consists of relationships that need time and responsibility.'],
[['vicina','female neighbor'],['doposcuola','after-school activities'],['relazione','relationship'],['responsabilità','responsibility']],
[['Choose “the person with whom I speak”.','la persona con cui parlo','la persona con che parlo','la persona cui parlo con','A preposition such as con takes cui in this pattern.'],['What agrees in il cui figlio?','Il agrees with figlio.','Cui changes for the owner’s gender.','Il agrees with the owner regardless of figlio.','The article before possessive cui agrees with the possessed noun.'],['What does the neighbor organize?','After-school activities','Train trips','A photography sale','Una vicina che organizza il doposcuola.']],
'Describe a community member with three relative clauses: one subject, one direct object, and one prepositional.',
[T('Relative roles',['Role','Form','Example'],[['Subject','che','la donna che parla'],['Direct object','che','la lettera che leggo'],['After preposition','cui','la persona con cui parlo'],['Possession','article + cui','la donna il cui figlio canta'],['Formal alternative','il quale / la quale / i quali / le quali','la sala nella quale lavoriamo']])]);
L('Indefinites, negatives, and participation','Use qualcuno, nessuno, niente, and ogni without overgeneralizing.',
'Qualcuno means someone; qualcosa means something. Nessuno and niente/nulla are negative. When a negative term follows the verb, non usually appears too: non vedo nessuno, non capisco niente. When nessuno is the subject before the verb, normally omit non: nessuno parla.\n\nOgni takes a singular noun and verb: ogni persona ha una storia. Tutti/tutte takes plural reference: tutte le persone hanno una storia. Distinguish a specific observation from a universal claim. In cultural analysis, words such as alcuni, molti, and in questo gruppo can make the scope of evidence clearer than tutti gli italiani.',
['Nessuno parla; non sento niente.','Nobody speaks; I hear nothing.','A preverbal negative subject and a postverbal negative object follow different patterns.'],['Ogni persona ha una storia.','Each person has a story.','Ogni takes singular agreement.'],
['Prima di lasciare Napoli, Giulia legge la pagina a Elena. Nessuno vuole cancellare le differenze tra le esperienze raccolte. Alcuni residenti parlano di aiuto, altri di fatica; non tutti hanno tempo per partecipare alle stesse attività. Sofia sostituisce una frase troppo generale con “in questo gruppo”. Il quaderno diventa più preciso proprio quando smette di fingere di spiegare ogni famiglia.','Before leaving Naples, Giulia reads the page to Elena. Nobody wants to erase differences between experiences. Some residents speak of support, others of effort; not everyone has time for the same activities. Sofia replaces an overly general sentence with “in this group.” The notebook becomes more precise when it stops pretending to explain every family.'],
[['qualcuno','someone'],['nessuno','nobody'],['fatica','effort / fatigue'],['partecipare','to participate']],
[['Choose the standard sentence with a negative subject.','Nessuno parla.','Nessuno non parla always means nobody speaks','Nessuno parlare.','A negative subject before the verb normally does not take an additional non.'],['Complete: Ogni persona ___ una storia.','ha','hanno','abbiamo','Ogni takes singular agreement.'],['What phrase does Sofia add for precision?','in questo gruppo','tutti gli italiani','senza differenze','She narrows the claim with in questo gruppo.']],
'Compare a practice in Elena’s fictional community with one you know. State what your evidence does and does not support.',
[T('Scope and negation',['Expression','Example','Pattern'],[['qualcuno','Qualcuno arriva.','Singular indefinite'],['nessuno before verb','Nessuno arriva.','No extra non normally'],['nessuno after verb','Non vedo nessuno.','Non with postverbal negative'],['ogni','Ogni persona ha…','Singular'],['tutti / tutte','Tutte le persone hanno…','Plural']])]);
// Chapter 6 — AP Language and Culture, Palermo
L('Trapassato prossimo','Place an event before another past reference point.',
'The trapassato prossimo uses an imperfect auxiliary and a past participle: avevo letto, eri partito, era arrivata. It marks something already completed before another past event. The auxiliary choice follows the same basic patterns as passato prossimo. With essere, keep subject agreement.\n\nUse it when the timeline needs a clear earlier layer: quando siamo arrivati, la guida era già partita. Già means already, prima means before. Do not use trapassato simply because an event feels distant; it needs a past reference point, explicit or understood. This is especially useful when explaining how an interview or discovery arose.',
['Quando siamo arrivati, la guida era già partita.','When we arrived, the guide had already left.','The departure precedes the past arrival.'],['Avevamo letto la lettera.','We had read the letter.','Imperfect avere + irregular participle.'],
['A Palermo, gli amici cercano una persona che Elena aveva consigliato. Giulia aveva scritto prima di partire, ma non aveva ricevuto una risposta. Quando arrivano alla biblioteca, scoprono che la referente aveva lasciato un messaggio alla reception. Aveva proposto un incontro sulle parole usate in famiglia e in pubblico. Sofia riapre la pagina di Napoli: il nuovo capitolo nasce da una domanda del precedente.','In Palermo, the friends seek someone Elena had recommended. Giulia had written before departure but had received no reply. At the library they learn that their contact had left a message at reception. She had proposed a meeting about words used at home and in public. Sofia reopens the Naples page: the new chapter grows from a question in the previous one.'],
[['già','already'],['biblioteca','library'],['messaggio','message'],['referente','contact person']],
[['Choose “we had read”.','avevamo letto','abbiamo letto','leggevamo','Imperfect avere + participle forms the pluperfect.'],['Does trapassato simply mean very long ago?','No; it locates an event before another past point.','Yes, it is determined only by age.','Only if the event is fictional.','Relative order, not distance from today, is central.'],['Who recommended the Palermo contact?','Elena','The Venice guide','An unnamed conductor','Una persona che Elena aveva consigliato.']],
'Explain how the Palermo interview was arranged, with three earlier events followed by the later discovery.',
[V('Trapassato prossimo',['leggere','partire'],[['avevo letto','avevi letto','aveva letto','avevamo letto','avevate letto','avevano letto'],['ero partito/a','eri partito/a','era partito/a','eravamo partiti/e','eravate partiti/e','erano partiti/e']])]);
L('Congiuntivo presente','Express evaluation, uncertainty, and desire with a dependent mood.',
'The congiuntivo often occurs after expressions of desire, doubt, emotion, or evaluation: spero che venga, penso che sia utile. It is a mood rather than a synonym for the future. Regular -are verbs use parli, parli, parli, parliamo, parliate, parlino; -ere and many -ire verbs use endings with a in the singular.\n\nSome stems are irregular: essere gives sia, avere abbia, fare faccia, andare vada. The singular forms often coincide, so an explicit subject can clarify the reference. Indicative and subjunctive selection depends on construction and meaning; do not change every verb after che mechanically. Compare so che viene with spero che venga.',
['Spero che Giulia venga.','I hope Giulia comes.','Sperare commonly introduces a subjunctive clause.'],['So che Giulia viene.','I know Giulia is coming.','A statement of known information takes the indicative here.'],
['La referente di Palermo chiede quale lingua ciascuno usi in famiglia. Sofia pensa che la domanda sia semplice, ma le risposte mostrano il contrario. Una partecipante spiega che sceglie parole diverse con la nonna e con i colleghi. Giulia spera che il quaderno conservi queste differenze senza ridurle a una gerarchia tra modi di parlare. Luca propone di ascoltare prima di scegliere una definizione.','The Palermo contact asks which language each person uses at home. Sofia thinks the question is simple, but the answers show otherwise. One participant chooses different words with her grandmother and colleagues. Giulia hopes the notebook preserves these differences without reducing them to a hierarchy of ways of speaking. Luca suggests listening before choosing a definition.'],
[['lingua','language / tongue'],['differenza','difference'],['scegliere','to choose'],['collega','colleague']],
[['Complete: Penso che sia ___. Which mood is sia?','Congiuntivo presente','Futuro semplice','Imperativo plural','Sia is present subjunctive of essere.'],['Choose the natural verb after spero che lei.','venga','viene','venuta','Sperare commonly selects congiuntivo: venga.'],['Why do the answers complicate the question?','People choose different words in different relationships.','Everyone speaks identically.','Nobody has a family.','The participant describes different choices with grandmother and colleagues.']],
'Offer an opinion, a hope, and a doubt about language learning. Name the subject clearly in each dependent clause.',
[V('Congiuntivo presente',['parlare','leggere','capire','essere','avere'],[['parli','parli','parli','parliamo','parliate','parlino'],['legga','legga','legga','leggiamo','leggiate','leggano'],['capisca','capisca','capisca','capiamo','capiate','capiscano'],['sia','sia','sia','siamo','siate','siano'],['abbia','abbia','abbia','abbiamo','abbiate','abbiano']])]);
L('Congiuntivo passato','Evaluate an action completed before the main reference.',
'The congiuntivo passato combines present subjunctive avere or essere with a participle: abbia letto, sia arrivata. It commonly places the dependent action before a present evaluation: penso che abbia capito, I think he/she understood. Auxiliary choice and agreement follow familiar compound-tense patterns.\n\nDistinguish mood from time. Spero che venga concerns a present/future arrival; spero che sia arrivata concerns an already completed arrival. Non credo che abbiano finito expresses doubt about completion. A present main verb does not force a present-time action in the dependent clause. Use explicit time markers to make the sequence clear.',
['Penso che abbia capito.','I think he/she understood.','Abbia + capito places the action before the present evaluation.'],['Spero che siano arrivate.','I hope they have arrived.','Essere and feminine plural agreement apply.'],
['Dopo l’incontro, Giulia controlla le registrazioni. Teme che alcune parole siano state capite male, perché il rumore copriva una voce. Sofia pensa che abbiano annotato abbastanza contesto per chiedere un chiarimento. Luca spera che le partecipanti abbiano ricevuto il messaggio di ringraziamento. Prima di pubblicare una citazione, vogliono verificare che il significato non sia cambiato nel passaggio dalla conversazione alla pagina.','After the meeting, Giulia checks the recordings. She fears some words were misunderstood because noise covered one voice. Sofia thinks they recorded enough context to request clarification. Luca hopes the participants received their thank-you message. Before publishing a quotation they want to verify that its meaning has not changed from conversation to page.'],
[['rumore','noise'],['chiarimento','clarification'],['citazione','quotation'],['significato','meaning']],
[['Choose a completed subjunctive action.','che abbia letto','che legga','che legge','Abbia letto is the past subjunctive, built with an auxiliary and participle.'],['Complete: Spero che Sofia sia ___.','arrivata','arrivato','arrivare','The essere participle agrees with feminine singular Sofia.'],['Why do they check a quotation?','To preserve its meaning and context','To make it sound more dramatic','To remove its speaker','They verify meaning before publication.']],
'Describe three uncertainties about a completed interview using congiuntivo passato.',
[V('Congiuntivo passato',['leggere','arrivare'],[['abbia letto','abbia letto','abbia letto','abbiamo letto','abbiate letto','abbiano letto'],['sia arrivato/a','sia arrivato/a','sia arrivato/a','siamo arrivati/e','siate arrivati/e','siano arrivati/e']])]);
L('Congiuntivo imperfetto','Place a dependent desire or doubt in a past-time frame.',
'The imperfect subjunctive forms include parlassi, leggessi, dormissi, with singular endings -ssi, -ssi, -sse and plural -ssimo, -ste, -ssero after the appropriate vowel. Essere is fossi, fossi, fosse, fossimo, foste, fossero. Learn the plural forms rather than extending a singular shortcut.\n\nA past wish often frames a simultaneous or later dependent event: speravo che venisse. Volevo che parlasse expresses what someone wanted another person to do. With the same subject, an infinitive is usually simpler: volevo parlare. These forms also appear in hypothetical conditions, introduced in the Art and Creativity chapter.',
['Speravo che Giulia venisse.','I hoped Giulia would come.','A past hope with a dependent imperfect subjunctive.'],['Volevo parlare con lei.','I wanted to speak with her.','The same-subject infinitive avoids an unnecessary second clause.'],
['La bibliotecaria racconta come aveva preparato l’incontro. Voleva che i partecipanti portassero una parola importante per loro. Sperava che nessuno si sentisse giudicato per l’accento. Giulia spiega che anche lei desiderava capire meglio le scelte dei parlanti, non correggere ogni differenza. Per il quaderno, gli amici decidono di raccontare la domanda e le risposte, ma anche il modo in cui l’incontro era stato organizzato.','The librarian describes preparing the meeting. She wanted participants to bring a word important to them and hoped nobody would feel judged for their accent. Giulia also wanted to understand speakers’ choices rather than correct every difference. The notebook will describe not only the question and answers but how the meeting was organized.'],
[['accento','accent'],['parlante','speaker'],['giudicare','to judge'],['scelta','choice']],
[['Complete: Speravo che lei ___.','venisse','viene','verrà','A past hope commonly takes imperfect subjunctive venisse.'],['Choose the first-person plural of essere in imperfect subjunctive.','fossimo','fossero','foste','Noi takes fossimo.'],['What did the librarian want participants to bring?','An important word','A museum ticket','A new phone','Una parola importante per loro.']],
'Explain the aims of a past community activity with voleva che and sperava che.',
[V('Congiuntivo imperfetto',['parlare','leggere','dormire','essere'],[['parlassi','parlassi','parlasse','parlassimo','parlaste','parlassero'],['leggessi','leggessi','leggesse','leggessimo','leggeste','leggessero'],['dormissi','dormissi','dormisse','dormissimo','dormiste','dormissero'],['fossi','fossi','fosse','fossimo','foste','fossero']])]);
L('Sequence of tenses','Relate a dependent event to a present or past viewpoint.',
'Choose a dependent tense by both the main viewpoint and the event’s relative time. Penso che venga and penso che sia venuta contrast a non-completed versus earlier completed arrival. Pensavo che venisse moves the viewpoint into the past. The trapassato subjunctive avesse letto or fosse arrivata can place an event before that past viewpoint.\n\nSequence is a meaning-based guide, not an instruction to replace every present after any past word. A reported statement about a still-valid fact can use a different pattern from a past wish. Draw a simple timeline: evaluation point, dependent action, then speaking time. Use the model chart to explain the ordering before choosing endings.',
['Pensavo che fosse già arrivata.','I thought she had already arrived.','Fosse + participle places arrival before a past thought.'],['Penso che venga domani.','I think he/she is coming tomorrow.','A present viewpoint can frame a later dependent action.'],
['Sofia confronta le prime note con il racconto della bibliotecaria. Pensava che tutti avessero scelto una parola prima dell’incontro; scopre invece che alcuni l’avevano cambiata durante la discussione. La differenza è importante: il significato non era un oggetto già pronto, ma qualcosa costruito nel dialogo. Giulia aggiunge una linea del tempo al quaderno per non confondere ciò che sapevano prima con ciò che avevano imparato dopo.','Sofia compares her notes with the librarian’s account. She thought everyone had chosen a word before the meeting; instead, some changed it during the discussion. The difference matters: meaning was not a ready-made object but something built in dialogue. Giulia adds a timeline so they do not confuse prior knowledge with what they learned afterwards.'],
[['prima','before'],['dopo','after'],['dialogo','dialogue'],['confrontare','to compare']],
[['Which action is earlier in pensavo che fosse arrivata?','The arrival','The thought','They must be simultaneous','Trapassato subjunctive places arrival before the past thought.'],['Which form fits an earlier completed action after penso che?','sia arrivata','venga' ,'arrivare always regardless of subject','Present evaluation plus earlier action commonly uses past subjunctive.'],['What do they add to clarify the order?','A timeline','A price list','A family tree','Giulia adds una linea del tempo.']],
'Summarize how an opinion changed after an interview. Use one present and one past evaluation, with correctly ordered dependent actions.',
[T('Relative time chart',['Main viewpoint','Dependent timing','Example'],[['Present','simultaneous / later','Penso che venga.'],['Present','earlier completed','Penso che sia venuta.'],['Past','simultaneous / later','Pensavo che venisse.'],['Past','earlier completed','Pensavo che fosse venuta.']]),V('Congiuntivo trapassato',['leggere'],[['avessi letto','avessi letto','avesse letto','avessimo letto','aveste letto','avessero letto']])]);
L('Register and linguistic identity','Choose Lei, forms of address, and language suited to a setting.',
'Polite Lei uses third-person singular verbs and often corresponding object forms: La ringrazio, Le scrivo. Capitalization of courteous pronouns is optional in many modern contexts, but consistency makes a formal note easier to follow. Voi normally addresses more than one person in standard usage; regional traditions can differ.\n\nRegister includes vocabulary, greeting, request form, and closing, not just pronoun choice. Gentile dottoressa opens a different relationship from Ciao Giulia. Standard Italian, regional varieties, and local languages have distinct histories; an accent is not evidence that a person has nothing valuable to say. Support cultural claims with a named source and a clear setting.',
['Le scrivo per chiedere un chiarimento.','I am writing to ask you for clarification.','Le is a polite indirect object here.'],['La ringrazio per il tempo dedicato.','Thank you for your time.','La is the polite direct object of ringraziare.'],
['Prima di lasciare Palermo, Giulia invia una richiesta alla bibliotecaria. Usa un saluto formale, spiega la domanda e ringrazia per il tempo. Luca nota che il contenuto è simile a quello di un messaggio a Elena, ma il rapporto è diverso. Sofia propone di affiancare nel quaderno due esempi originali di registro, spiegando quando sono stati usati. La prossima tappa, Milano, porterà la domanda dalla voce quotidiana alla voce musicale.','Before leaving Palermo, Giulia sends the librarian a request. She uses a formal greeting, explains the question, and gives thanks. Luca notes that the content resembles a message to Elena but the relationship differs. Sofia proposes two original register examples with their contexts. Milan, the next stop, will take the question from everyday voice to musical voice.'],
[['registro','register'],['richiesta','request'],['ringraziare','to thank'],['quotidiano','everyday']],
[['Choose polite “I write to you”.','Le scrivo.','Ti scrivo.','Vi scrivo always for polite singular','Le is polite singular indirect object.'],['What determines an appropriate register?','Relationship, setting, and communicative purpose','Only the number of words','Only whether the speaker is Italian','Register responds to context, audience, and purpose.'],['Where are they going next?','Milano','Roma','Bologna','La prossima tappa is Milano.']],
'Ask a classmate for clarification, then ask the librarian. Explain two changes in register.',
[T('Register choices',['Function','Familiar','Polite / formal'],[['Greeting','Ciao, Giulia!','Gentile dottoressa,'],['Ask','Ti chiedo…','Le chiedo…'],['Thank','Ti ringrazio.','La ringrazio.'],['Request','Puoi aiutarmi?','Può aiutarmi?'],['Closing','A presto!','Cordiali saluti,']])]);
// Chapter 7 — AP Art and Creativity, Milano
L('Condizionale presente','Express hypothetical outcomes and courteous requests.',
'The conditional uses the future-like stem with -ei, -esti, -ebbe, -emmo, -este, -ebbero: parlerei, parleresti, parlerebbe. Irregular future stems also appear: sarei, avrei, andrei, farei, potrei, vorrei. Distinguish noi -emmo from future -emo.\n\nUse it for an imagined outcome, an attenuated opinion, or a courteous request: vorrei un biglietto, potrebbe spiegare? A conditional does not require an explicit if-clause every time. In a cultural discussion, direi can soften an interpretation without supplying evidence. State why you think something, rather than letting a polite form stand in for support.',
['Vorrei ascoltare il concerto.','I would like to hear the concert.','Vorrei softens a desire.'],['Potrebbe spiegare questo passaggio?','Could you explain this passage?','Third-person conditional works for polite Lei.'],
['A Milano, Sofia vorrebbe capire come una canzone cambia significato in luoghi diversi. Giulia chiederebbe a una cantante di parlare del pubblico, mentre Luca farebbe domande sulla registrazione. Alla fine scrivono una richiesta breve al museo teatrale. Non chiedono una risposta che rappresenti tutta la musica italiana: vogliono partire da un’opera, una pratica e un contesto precisi.','In Milan, Sofia would like to understand how a song changes meaning across places. Giulia would ask a singer about audiences, while Luca would ask about recording. They write a short request to the theater museum. They are not seeking an answer representing all Italian music, but a specific work, practice, and context.'],
[['concerto','concert'],['cantante','singer'],['pubblico','audience / public'],['opera','work / opera']],
[['Complete: Noi ___ con la cantante.','parleremmo','parleremo','parleranno','Conditional noi has -emmo; future noi has -emo.'],['Which form is a polite could you with Lei?','potrebbe','potresti','potete','Lei takes third-person singular potrebbe.'],['Why do they narrow their request?','To study a specific work and context','To claim all music is identical','To avoid listening to music','They choose an opera, pratica e contesto precisi.']],
'Make three polite questions for a musician and say what you would investigate first.',
[V('Condizionale presente',['parlare','essere','potere'],[['parlerei','parleresti','parlerebbe','parleremmo','parlereste','parlerebbero'],['sarei','saresti','sarebbe','saremmo','sareste','sarebbero'],['potrei','potresti','potrebbe','potremmo','potreste','potrebbero']])]);
L('Imperatives and invitations','Give familiar and polite instructions, including clitic placement.',
'An affirmative tu command often uses third-person present for -are verbs: parla! For -ere/-ire, it often resembles second-person present: leggi!, dormi!, finisci! Polite Lei uses present subjunctive forms: parli!, legga! Noi and voi usually match the corresponding present forms. Irregulars such as fa’/fai, va’/vai, and di’ require attention.\n\nA negative tu command uses non + infinitive: non parlare! Positive familiar commands attach pronouns: ascoltala! Negative forms can use non ascoltarla or non la ascoltare. With polite commands, pronouns precede: la ascolti. Select the register before choosing the command form.',
['Ascolta la voce; ascoltala bene.','Listen to the voice; listen to it carefully.','The pronoun attaches to the familiar affirmative command.'],['Non parlare durante l’ascolto.','Do not speak while listening.','Negative tu uses the infinitive.'],
['Una mediatrice del museo accoglie il gruppo: «Ascoltate prima il brano, poi osservate l’immagine. Non cercate subito una traduzione parola per parola». Giulia prende nota. La mediatrice aggiunge: «Chiedetevi chi parla, a chi si rivolge e quale effetto cerca». Luca spegne il telefono. Per una volta, la pagina del quaderno comincia da un ascolto intero, non da una fotografia presa in fretta.','A museum mediator welcomes the group: “Listen to the piece first, then look at the image. Do not immediately seek a word-for-word translation.” She adds: “Ask who is speaking, to whom, and with what intended effect.” Luca turns off his phone. For once the page begins with a complete listening, not a rushed photograph.'],
[['ascolto','listening'],['brano','piece / excerpt'],['effetto','effect'],['in fretta','in a hurry']],
[['Choose a negative tu command.','Non parlare!','Non parla!','Non parlato!','Negative tu uses non + infinitive.'],['Choose the polite singular command for leggere.','Legga!','Leggi!','Leggete!','Lei commands use present subjunctive legga.'],['What should they do first?','Listen to the entire piece','Translate every word immediately','Take a photo','Ascoltate prima il brano.']],
'Give instructions for an attentive listening activity, first to a friend and then to a formal audience.',
[T('Imperatives',['Verb','tu affirmative','tu negative','Lei polite','voi'],[['parlare','parla','non parlare','parli','parlate'],['leggere','leggi','non leggere','legga','leggete'],['dormire','dormi','non dormire','dorma','dormite'],['finire','finisci','non finire','finisca','finite'],['dire','di’','non dire','dica','dite']]),T('Command pronouns',['Familiar positive','Familiar negative','Polite'],[['Ascoltala!','Non ascoltarla! / Non la ascoltare!','La ascolti.']])]);
L('Hypothetical conditions','Combine se + imperfect subjunctive with a conditional result.',
'An open condition commonly uses the indicative: se ho tempo, vengo. A hypothetical present situation uses imperfect subjunctive after se and a conditional in the result: se avessi tempo, verrei. Do not place conditional avrei in that standard se clause.\n\nMeaning determines the choice. The hypothetical pattern can describe an imagined opportunity, a remote possibility, or a situation contrary to present facts. It does not automatically mean an impossible dream. A modal result is possible: se avessi più dati, potrei confrontarli. This supports careful discussion of what further evidence would allow you to conclude.',
['Se avessi tempo, verrei.','If I had time, I would come.','Imperfect subjunctive condition, conditional result.'],['Se ho tempo, vengo.','If I have time, I will come.','An open possibility can use the indicative.'],
['Dopo l’ascolto, Luca immagina una mostra fatta soltanto di suoni. Se avesse più tempo, registrerebbe anche i silenzi tra una prova e l’altra. Giulia osserva che, se ascoltassero soltanto un artista, non potrebbero descrivere un’intera scena musicale. Sofia propone di confrontare due testimonianze, senza fingere che il confronto sia completo. Il progetto diventa una domanda più piccola, ma più verificabile.','After listening, Luca imagines an exhibition made only of sounds. With more time, he would record the silences between rehearsals too. Giulia notes that listening to only one artist would not describe an entire musical scene. Sofia proposes comparing two accounts without pretending the comparison is complete. The project becomes smaller but more testable.'],
[['silenzio','silence'],['prova','rehearsal / test'],['testimonianza','account / testimony'],['verificabile','verifiable']],
[['Choose a standard hypothetical condition.','Se avessi tempo, verrei.','Se avrei tempo, verrei.','Se avrò tempo, venuto.','Use imperfect subjunctive in the se clause and conditional in the result.'],['Which form describes an open possibility?','Se ho tempo, vengo.','Se avessi tempo, verrei.','Se avessi avuto tempo, sarei venuto.','The indicative presents the condition as open.'],['What does Giulia warn against?','Generalizing from one artist to a whole scene','Listening to two sources','Writing any questions','One artist does not represent an entire musical scene.']],
'Explain what you would add to a music project if you had more time, access, or source material.',
[T('Condition patterns',['Type','If-clause','Result'],[['Open','Se ho tempo,','vengo.'],['Hypothetical present','Se avessi tempo,','verrei.'],['Hypothetical with modal','Se avessi più dati,','potrei confrontarli.']])]);
L('Condizionale passato and unreal past','Imagine a different outcome and express future-in-the-past.',
'The past conditional combines conditional avere/essere with a participle: avrei letto, sarei arrivata. A past counterfactual pairs it with trapassato subjunctive: se avessi saputo, sarei venuta. Both actions concern a different imagined past; preserve auxiliary choice and participle agreement.\n\nItalian also uses the past conditional for future-in-the-past: ha detto che sarebbe venuta, she said she would come. This does not by itself prove she failed to come. Timeline and context distinguish a reported later event from an unreal outcome. The English word would is therefore not a sufficient tense-selection rule.',
['Se avessi saputo, sarei venuta.','If I had known, I would have come.','Past unreal condition plus past conditional result.'],['Ha detto che sarebbe venuta.','She said she would come.','Future-in-the-past does not automatically mean she never came.'],
['La cantante aveva detto che sarebbe arrivata dopo la prova. Gli amici l’hanno aspettata nella sala, ma un problema tecnico ha cambiato l’orario. Se avessero controllato il messaggio, avrebbero saputo del ritardo. Quando finalmente si incontrano, Giulia non presenta l’attesa come un fallimento: era un limite concreto del loro metodo. Aggiunge al quaderno una nota sulle condizioni in cui l’intervista è stata realizzata.','The singer had said she would arrive after rehearsal. The friends waited, but a technical problem changed the schedule. Had they checked the message, they would have known about the delay. When they meet, Giulia treats the wait as a limitation of their method, not a failure, and notes the conditions of the interview.'],
[['ritardo','delay'],['metodo','method'],['limite','limitation'],['tecnico','technical']],
[['Which is the past conditional of leggere for io?','avrei letto','avessi letto','ho letto','Avrei + participle is conditional past; avessi letto is subjunctive pluperfect.'],['Does sarebbe venuta in reported speech prove non-arrival?','No','Always','Only with Lei','It can express a later event from a past viewpoint.'],['What caused the schedule change?','A technical problem','A missing book','A train strike in the passage','Un problema tecnico ha cambiato l’orario.']],
'Retell a changed plan with a reported future, then imagine an alternative past with se… avrei/sarei….',
[V('Condizionale passato',['leggere','arrivare'],[['avrei letto','avresti letto','avrebbe letto','avremmo letto','avreste letto','avrebbero letto'],['sarei arrivato/a','saresti arrivato/a','sarebbe arrivato/a','saremmo arrivati/e','sareste arrivati/e','sarebbero arrivati/e']]),T('Two meanings',['Example','Function'],[['Se avessi saputo, sarei venuta.','Unreal past outcome'],['Ha detto che sarebbe venuta.','Later event from a past viewpoint']])]);
L('Passato remoto in narrative','Recognize literary completed-past forms and their register.',
'The passato remoto is a completed narrative past used in literature and with different frequencies across regions. Distance from today alone does not determine its use. Common forms include fu, disse, fece, vide, venne. Recognize the third-person forms that advance a written story.\n\nRegular paradigms include parlai/parlasti/parlò and dormii/dormisti/dormì. Many -ere verbs are irregular, sometimes alternating regular and irregular stems across persons. Compare a narration’s disse with the conversational ha detto and the background diceva. Identifying the tense helps you separate event sequence from setting without assuming an old text uses unfamiliar grammar in every sentence.',
['La cantante aprì il quaderno e sorrise.','The singer opened the notebook and smiled.','Two completed narrative events in passato remoto.'],['Disse che la musica era memoria.','She said music was memory.','Disse advances the narrative; era describes the proposition.'],
['La cantante aprì il quaderno e lesse le domande. Disse che una canzone non era soltanto il testo scritto: cambiava con la voce, il luogo e chi ascoltava. Luca pose una domanda sulla registrazione; lei indicò il microfono e sorrise. Giulia annotò le parole, poi aggiunse il contesto. Nella versione narrativa della pagina, il passato remoto rese visibile la sequenza, mentre l’imperfetto lasciava spazio alle spiegazioni.','The singer opened the notebook and read the questions. She said a song was not just its written words: it changed with voice, place, and listener. Luca asked about recording; she pointed to the microphone and smiled. Giulia recorded the words, then the context. Their narrative used remote past for the sequence and imperfect for explanations.'],
[['sorridere','to smile'],['microfono','microphone'],['sequenza','sequence'],['spiegazione','explanation']],
[['Which is literary completed past?','disse','diceva','dice','Disse is passato remoto; diceva is imperfect and dice is present.'],['Does remoto always mean an event must be centuries old?','No; register and regional usage matter.','Yes, without exception','Only if a date is written','Its use is not governed by a universal age threshold.'],['What does the singer say changes a song?','Voice, place, and listener','Only the written title','Only the ticket price','Cambiava con la voce, il luogo e chi ascoltava.']],
'Retell three events with passato prossimo, then replace them with recognizable literary forms.',
[V('Passato remoto',['parlare','dormire','essere'],[['parlai','parlasti','parlò','parlammo','parlaste','parlarono'],['dormii','dormisti','dormì','dormimmo','dormiste','dormirono'],['fui','fosti','fu','fummo','foste','furono']]),T('Frequent narrative forms',['Infinitive','Third-person singular'],[['dire','disse'],['fare','fece'],['vedere','vide'],['venire','venne'],['leggere','lesse'],['aprire','aprì']])]);
L('Close reading and artistic interpretation','Distinguish literal grammar, evidence, and a supported reading.',
'Begin a close reading by identifying speaker, grammatical subject, verb, imagery, and setting. In Dante’s “Nel mezzo del cammin di nostra vita”, cammin is an apocopated form of cammino and di nostra vita modifies the journey. The contracted opening nel combines in + il. Literary form can preserve older words and orders without making the whole passage untranslatable.\n\nA cultural interpretation needs evidence. Mi ritrovai is first-person passato remoto; the speaker locates an experience from a later narrative viewpoint. Do not assume the historical author, narrator, and every listener have identical perspectives. A short supported interpretation is stronger than a large claim detached from the words or performance.',
['Nel mezzo del cammin di nostra vita.','In the middle of the journey of our life.','Cammin is a shortened literary form of cammino.'],['Mi ritrovai per una selva oscura.','I found myself in a dark wood.','Ritrovai is first-person passato remoto.'],
['Prima di lasciare Milano, Giulia legge l’inizio dell’Inferno: «Nel mezzo del cammin di nostra vita / mi ritrovai per una selva oscura». Sofia riconosce nel e del, ma nota che il testo non è una conversazione quotidiana. Luca collega il viaggio del quaderno al cammino del verso, poi corregge la propria frase: è un’associazione personale, non la prova che i due viaggi abbiano lo stesso significato. Decidono di portare questa distinzione a Torino, dove studieranno immagini, strumenti e dati.','Before leaving Milan, Giulia reads the opening of the Inferno. Sofia recognizes nel and del but notes the literary register. Luca connects their journey to the verse, then corrects himself: a personal association does not prove the journeys have the same meaning. They take this distinction to Turin, where they will study images, instruments, and data.'],
[['cammino','path / journey'],['selva','wood / forest (literary)'],['interpretazione','interpretation'],['prova','evidence / test / rehearsal']],
[['What is cammin in the quoted line?','A shortened literary form of cammino','A second-person command','An indirect object pronoun','Cammin is an apocopated noun form.'],['Which form marks the speaker’s completed narrative event?','mi ritrovai','nostra','oscura','Ritrovai is first-person passato remoto.'],['How does Luca qualify his comparison?','As a personal association rather than proof','As a verified identity of meaning','As a rule for every reader','He explicitly separates association and evidence.']],
'Read the two lines, paraphrase them, and support one interpretation with a specific grammatical or lexical feature.',
[T('Annotating Dante',['Phrase','Grammar','Reading aid'],[['nel mezzo','in + il + noun','in the middle'],['del cammin','di + il; shortened noun','of the journey'],['di nostra vita','possessive + feminine noun','of our life'],['mi ritrovai','first-person remote past with clitic','I found myself'],['una selva oscura','indefinite article + noun + adjective','a dark wood']],'Public-domain source: Dante, Inferno I, lines 1–2; original text linked in Readings.')]);
// Chapter 8 — AP Science and Technology, Torino
L('Passive voice and agency','Shift focus to the affected object and keep participles in agreement.',
'The passive uses essere and an agreeing participle: il film è proiettato, le immagini sono proiettate. The active object becomes the passive subject. An agent can appear with da: il film è proiettato dal museo. Choose tense on essere: è stato restaurato, sarà restaurato.\n\nIn simple tenses, venire can emphasize a passive event: viene proiettato. Not every essere + adjective-shaped participle describes an action; la porta è chiusa may simply describe a state. Ask what the source foregrounds and whether it names the actor. Passive grammar alone does not make a statement objective or prove its claim.',
['Le immagini sono conservate dal museo.','The images are preserved by the museum.','Conservate agrees with feminine plural immagini.'],['Il film viene proiettato ogni sera.','The film is shown every evening.','Venire forms an event passive in a simple tense.'],
['A Torino, gli amici visitano un museo dedicato al cinema. Alcune immagini sono conservate in condizioni controllate; altre vengono mostrate attraverso strumenti che cambiano l’esperienza del pubblico. Sofia domanda chi abbia deciso il percorso. Luca nota che un cartello usa la forma passiva senza nominare il responsabile del restauro. Giulia scrive una domanda nel quaderno: una spiegazione può descrivere bene una tecnica e lasciare comunque poco chiaro chi prende le decisioni.','In Turin, the friends visit a cinema museum. Some images are kept under controlled conditions; others are shown through devices that change the audience’s experience. Sofia asks who chose the route. Luca notices a passive notice that omits the restorer. Giulia asks whether a good technical explanation can still leave decision-making unclear.'],
[['conservare','to preserve'],['strumento','instrument / tool'],['restauro','restoration'],['responsabile','person responsible']],
[['Complete: Le immagini sono ___.','conservate','conservato','conservata','The passive participle agrees with feminine plural immagini.'],['Which preposition normally introduces the passive agent?','da','a','con always','Da identifies the agent in dal museo.'],['What information does Luca find missing?','Who was responsible for restoration','The city name','The word cinema','The notice omits the responsible actor.']],
'Transform three active descriptions into passives and identify which agents remain visible.',
[T('Passive agreement',['Subject','Present','Completed past','Future'],[['il film','è conservato','è stato conservato','sarà conservato'],['la foto','è conservata','è stata conservata','sarà conservata'],['i film','sono conservati','sono stati conservati','saranno conservati'],['le foto','sono conservate','sono state conservate','saranno conservate']])]);
L('Si impersonale and si passivante','Describe general practice and distinguish singular from plural agreement.',
'Impersonal si frames an action without a specific subject: qui si lavora molto. With an intransitive verb it normally uses third-person singular. Passive si with a transitive verb can agree with the affected noun: si vende un libro, si vendono libri. Determine the construction before treating every si as reflexive.\n\nWhen reflexive si combines with impersonal si, the first changes to ci: ci si sveglia presto. In a general personal description, an adjective can appear in plural masculine: quando si è stanchi. Signs and institutional explanations often use these patterns; they can describe practices without naming a particular worker.',
['Qui si vendono libri.','Books are sold here.','Plural libri takes plural vendono in this passive-like construction.'],['Ci si sveglia presto.','One gets up early.','Ci avoids a repeated si si cluster.'],
['Nel laboratorio del museo si lavora con attenzione. Si controllano i supporti, si confrontano copie e si registrano le modifiche. La guida spiega che non si può trattare ogni materiale nello stesso modo. Luca chiede se si conservino anche le tracce dei vecchi strumenti. Per il quaderno, Sofia riscrive la procedura con un soggetto esplicito: così gli amici vedono meglio quali competenze servono dietro una formula impersonale.','In the museum laboratory people work carefully. Media are checked, copies compared, and changes recorded. The guide explains that not all materials can be treated alike. Luca asks whether traces of old tools are preserved too. Sofia rewrites the procedure with an explicit subject to reveal the expertise behind an impersonal formula.'],
[['supporto','medium / support'],['modifica','change'],['competenza','skill / expertise'],['procedura','procedure']],
[['Choose passive si with plural libri.','Si vendono libri.','Si vende libri. as the standard agreement model','Si vendere libri.','Passive si agrees with plural libri.'],['How does impersonal si combine with a reflexive?','ci si','si si','lo si si','Ci si replaces the repeated si sequence.'],['Why does Sofia add explicit subjects?','To reveal the skills and people behind a procedure','To remove all workers','To make a claim automatically true','The passage names the competenze behind the impersonal wording.']],
'Describe three laboratory rules with si, then rewrite each with a named person or institution.',
[T('Si constructions',['Construction','Example','Key point'],[['Impersonal','Qui si lavora.','Singular finite verb'],['Passive singular','Si vende un libro.','Singular affected subject'],['Passive plural','Si vendono libri.','Plural agreement'],['Reflexive + impersonal','Ci si sveglia presto.','Avoid si si'],['General description','Quando si è stanchi…','Adjective often masculine plural']])]);
L('Gerundio and progressive aspect','Describe an action underway and an accompanying action.',
'The gerund ends in -ando for -are and -endo for many -ere/-ire verbs: parlando, leggendo, dormendo. Some stems are irregular: facendo, dicendo, bevendo. Stare + gerund emphasizes an action in progress: sto leggendo. Italian also uses a plain present in many contexts where English uses a progressive.\n\nA gerund can describe a simultaneous action: camminava parlando. Keep its understood subject aligned with the main clause unless a clearly marked construction says otherwise. Object clitics can attach to the gerund: leggendolo; with progressive stare, lo sto leggendo is also possible. A perfect gerund such as avendo letto places an action earlier.',
['Sto leggendo il rapporto.','I am reading the report.','Stare + gerund highlights an ongoing action.'],['Avendo letto il rapporto, possiamo discuterne.','Having read the report, we can discuss it.','The perfect gerund places reading before the discussion.'],
['Giulia sta ascoltando una spiegazione registrata mentre Sofia osserva un apparecchio. Luca, confrontando due immagini, nota una differenza che non aveva visto prima. Non sa ancora se dipenda dallo strumento o dal modo in cui l’immagine è stata presentata. Avendo annotato il contesto, può porre una domanda precisa. La tecnologia non diventa meno interessante quando ammettono di non capire subito il suo effetto.','Giulia listens to a recorded explanation while Sofia observes a device. Comparing two images, Luca notices a difference he missed. He does not yet know whether it comes from the device or presentation. Having noted the context, he can ask precisely. Technology remains interesting even when they admit they do not immediately understand its effect.'],
[['rapporto','report'],['apparecchio','device'],['dipendere','to depend'],['osservare','to observe']],
[['Choose the gerund of fare.','facendo','fando','fatto','Fare has irregular gerund facendo.'],['What is the function of sto leggendo?','To emphasize reading in progress','To mark a completed future','To form the imperative','Stare + gerund is progressive.'],['Does Luca already know the cause of the difference?','No','Yes, with certainty','The text says it is always the device','Non sa ancora se dipenda… makes uncertainty explicit.']],
'Describe what three people are doing, then state what you learned by comparing two objects.',
[V('Stare — present',['stare'],[['sto','stai','sta','stiamo','state','stanno']]),T('Gerunds',['Infinitive','Gerund','Progressive'],[['parlare','parlando','sto parlando'],['leggere','leggendo','sto leggendo'],['dormire','dormendo','sto dormendo'],['fare','facendo','sto facendo'],['dire','dicendo','sto dicendo'],['bere','bevendo','sto bevendo']])]);
L('Ci and ne','Replace places, quantities, and di phrases without losing reference.',
'Ci can replace a place expression: vado al museo → ci vado. It also appears in fixed verb patterns such as pensarci. Ne can replace a di phrase or a quantity introduced earlier: parlo del film → ne parlo; quanti libri hai? ne ho due. State the reference first so the pronoun is interpretable.\n\nCi sono means there are, while c’è means there is. These are different from si constructions. With a counted direct object in a compound past, ne commonly participates in agreement: di lettere, ne ho lette due. Not every ci means us and not every ne means some; analyze the verb’s construction.',
['Al museo? Ci vado domani.','To the museum? I am going there tomorrow.','Ci refers back to the place.'],['Di lettere, ne ho lette due.','Of the letters, I read two.','Ne preserves a quantity relation and the participle agrees here.'],
['Luca vuole tornare al laboratorio. Sofia ci è già stata, ma accetta di tornarci. Giulia ha tre domande sugli strumenti; ne ha scritte due e vuole formulare meglio la terza. Quando parlano del film, non ne discutono soltanto la trama: confrontano anche il modo in cui il museo lo presenta. Il quaderno raccoglie meno nomi di apparecchi e più domande sul loro uso.','Luca wants to return to the laboratory. Sofia has already been there but agrees to return. Giulia has three questions about the tools; she wrote two and wants to improve the third. When discussing the film, they consider not only the plot but its museum presentation. The notebook collects fewer device names and more questions about use.'],
[['tornare','to return'],['quantità','quantity'],['trama','plot'],['uso','use']],
[['What does ci replace in al museo? ci vado?','The place expression','A feminine direct object','Always a plural person','Ci can refer back to a place.'],['Choose “I have two of them” after libri.','Ne ho due.','Ci ho due.','Li ho di due.','Ne expresses the previously identified quantity relation.'],['How many questions has Giulia written?','Two','Three','One','Ne ha scritte due.']],
'Ask and answer questions about places, amounts, and topics, using ci and ne with explicit antecedents.',
[T('Pronoun references',['Explicit phrase','Replacement','Meaning'],[['Vado al museo.','Ci vado.','I go there.'],['Parlo del film.','Ne parlo.','I talk about it.'],['Ho due libri.','Ne ho due.','I have two of them.'],['Ci sono tre sale.','Ce ne sono tre.','There are three of them.'],['Ho letto due lettere.','Ne ho lette due.','I read two of them.']])]);
L('Comparisons and data language','Use più, meno, quanto, and percentage-point distinctions.',
'Comparatives commonly use più/meno + adjective + di: più grande di Roma. Che often compares two qualities, actions, or parallel complements: più utile che bello, più facile parlare che scrivere. Equality uses tanto… quanto or così… come. Adjectives still agree where appropriate.\n\nData language needs a denominator, time period, and measured group. An increase from 20% to 30% is ten percentage points, not automatically a ten-percent increase. No figures in this lesson describe real Italian survey results: the table is invented practice data. Distinguish a comparison supported by the table from an explanation of its cause, which requires more evidence.',
['Il secondo valore è più alto del primo.','The second value is higher than the first.','Di + il becomes del.'],['È più utile che bello.','It is more useful than beautiful.','Che compares two qualities of the same thing.'],
['Sofia prepara una tabella didattica con dati inventati per esercitare i confronti. Nel gruppo A, 20 persone su 100 usano un servizio; nel gruppo B, 30 su 100. Luca dice che il valore è aumentato del dieci per cento. Giulia lo corregge: la differenza è di dieci punti percentuali, mentre l’aumento relativo è del cinquanta per cento. Nessuno dei due numeri spiega perché i gruppi siano diversi.','Sofia makes an invented practice table. In group A, 20 out of 100 use a service; in group B, 30 out of 100 do. Luca calls it a ten-percent increase. Giulia corrects him: it is ten percentage points, while the relative increase is fifty percent. Neither number explains why the groups differ.'],
[['dato','data point'],['percentuale','percentage'],['aumento','increase'],['confronto','comparison']],
[['A change from 20% to 30% is how many percentage points?','10','50','30','Subtract the percentages: 30 − 20 = 10 percentage points.'],['Choose the comparison of two qualities.','più utile che bello','più utile di bello as this model','più utile quanto bello','Che compares the two qualities in this construction.'],['Are the table’s numbers real Italian survey results?','No, they are invented practice data.','Yes, a national census','Yes, an official AP dataset','The passage explicitly labels the figures as invented.']],
'Describe the invented table, name the denominator, and state one thing it cannot establish.',
[T('Invented practice data — not a real survey',['Group','Users','People measured','Share'],[['A','20','100','20%'],['B','30','100','30%'],['Difference','10','Same denominator','10 percentage points'],['Relative increase','10 ÷ 20','Baseline A','50%']]),T('Comparison structures',['Relationship','Example'],[['Two entities','più alto del primo'],['Two qualities','più utile che bello'],['Equality','tanto utile quanto chiaro'],['Relative superlative','il più utile del gruppo']])]);
L('Evidence, claims, and uncertainty','Use cautious constructions and attribute a conclusion to its source.',
'An observation is not automatically a causal explanation. Secondo il rapporto attributes a claim; i dati suggeriscono che frames a limited inference. È possibile che commonly takes subjunctive, while è certo che normally introduces an indicative assertion. Grammar can show your stance without deciding whether the evidence is good.\n\nWords such as forse, probabilmente, potrebbe, and non necessariamente limit certainty in different ways. Avoid stacking them until a sentence says nothing. Name the source, measured group, date, and limitation when needed. This supports interpretive analysis of reports and visualizations in AP work without inventing statistics or turning a fictional table into national evidence.',
['È possibile che i risultati cambino.','It is possible that the results change.','Possibility introduces a subjunctive clause.'],['Secondo il rapporto, il campione è limitato.','According to the report, the sample is limited.','The phrase attributes information rather than asserting universal knowledge.'],
['Prima di lasciare Torino, gli amici rivedono la pagina sulla tecnologia. Luca aveva scritto che uno strumento migliorava sempre l’esperienza. Sofia chiede: per chi, in quale situazione e secondo quale fonte? Non cancellano l’osservazione, ma ne restringono la portata. Giulia aggiunge che un’immagine più nitida non rende automaticamente più chiara un’interpretazione. Portano queste domande a Genova, dove parleranno di studio, lavoro e vita quotidiana.','Before leaving Turin, the friends revise their technology page. Luca wrote that one tool always improved the experience. Sofia asks: for whom, in what situation, according to which source? They narrow the claim without erasing the observation. Giulia notes that a sharper image does not automatically clarify interpretation. They take these questions to Genoa and everyday life.'],
[['fonte','source'],['campione','sample'],['risultato','result'],['portata','scope']],
[['Which phrase clearly attributes a claim?','Secondo il rapporto…','Tutti sanno…','È ovvio…','Secondo il rapporto names the source of the statement.'],['Choose a subjunctive after è possibile che i risultati.','cambino','cambiano','cambiato','A possibility construction commonly selects congiuntivo cambino.'],['What do they do to Luca’s claim?','Narrow its scope','Invent supporting numbers','Delete all observation','Ne restringono la portata.']],
'Present a limited claim from one source and explain what further evidence would be needed.',
[T('Stance and attribution',['Purpose','Expression','Grammar / effect'],[['Attribution','secondo il rapporto','Names a source'],['Possibility','è possibile che cambino','Subjunctive'],['Assertion','è certo che cambiano','Indicative in this asserted pattern'],['Tentative explanation','potrebbe dipendere da…','Conditional possibility'],['Limitation','non necessariamente','Not an automatic consequence']])]);
// Chapter 9 — AP Contemporary Life, Genova
L('Futuro anteriore','Order future events and distinguish conjecture about the past.',
'The future perfect uses future avere/essere and a participle: avrò letto, sarà arrivata. It can place completion before a later future point: quando avrò finito, uscirò. Italian may use the future perfect in a time clause where English uses a present perfect. Auxiliary and participle agreement follow familiar patterns.\n\nThe same form can express a conjecture about a completed past event: avrà perso il treno, perhaps he/she missed the train. The simple future can conjecture about the present: sarà a casa. Time expressions and context distinguish prediction from inference; do not present a guess as verified news merely because its grammar is confident.',
['Quando avrò finito, uscirò.','When I have finished, I will go out.','Future completion precedes the future exit.'],['Avrà perso il treno.','He/she probably missed the train.','The form can express conjecture about the past.'],
['A Genova, Giulia aspetta una studentessa che ha accettato di parlare del lavoro e dello studio. «Avrà perso l’autobus», dice Luca quando vede il ritardo. Sofia ricorda che è solo un’ipotesi. La studentessa arriva e spiega che aveva accompagnato una compagna. Dopo l’intervista, quando avranno completato le note, gli amici cercheranno una fonte che permetta di confrontare l’esperienza individuale con un quadro più ampio.','In Genoa, Giulia waits for a student who agreed to discuss work and study. Luca guesses she missed a bus; Sofia notes it is only a hypothesis. The student arrives and explains she accompanied a classmate. Once the interview notes are complete, they will seek a source that places the individual experience in a broader context.'],
[['lavoro','work'],['studio','study'],['ipotesi','hypothesis'],['compagna','female classmate / companion']],
[['Which completion is earlier in quando avrò finito, uscirò?','Finishing','Going out','They must happen simultaneously','Future perfect marks completion before the future exit.'],['Does avrà perso always report verified past fact?','No, it can mark a conjecture.','Yes','Only when it has no subject','The context can make future perfect a past conjecture.'],['Was Luca’s bus explanation confirmed?','No','Yes','The student never arrived','She explains a different reason for the delay.']],
'Plan three tasks that must be completed before another future task. Contrast one plan with a cautious guess.',
[V('Futuro anteriore',['finire','arrivare'],[['avrò finito','avrai finito','avrà finito','avremo finito','avrete finito','avranno finito'],['sarò arrivato/a','sarai arrivato/a','sarà arrivato/a','saremo arrivati/e','sarete arrivati/e','saranno arrivati/e']])]);
L('Reported statements and questions','Shift person, time references, and viewpoint carefully.',
'Reported statements commonly use che: dice che studia. A past viewpoint may shift the dependent tense: ha detto che studiava, or ha detto che sarebbe partita for a later event. Do not change tense blindly when the report asserts a fact still presented as current. Adjust here/today/tomorrow when the reporting situation changes.\n\nReported yes/no questions use se: ha chiesto se lavoravamo. Information questions retain the question word: ha chiesto dove studiavamo. Requests commonly use di + infinitive when addressed to the object: ci ha chiesto di aspettare. The choice expresses a communicative act, not a literal preservation of quotation punctuation.',
['Ha chiesto dove studiavamo.','He/she asked where we studied.','Keep the information question word dove.'],['Ci ha chiesto di aspettare.','He/she asked us to wait.','An addressed request takes di + infinitive here.'],
['Giulia riassume l’intervista di Genova senza usare soltanto citazioni. La studentessa ha detto che studiava e lavorava in orari diversi. Aveva chiesto agli amici se volessero parlare anche con una compagna e dove avrebbero presentato il progetto. Sofia controlla il riassunto: una domanda non deve diventare una promessa, e una possibilità non deve apparire come una decisione già presa. Nel quaderno distinguono voce diretta e discorso riportato.','Giulia summarizes the Genoa interview beyond quotations. The student said she studied and worked at different times. She asked whether they wanted to speak with a classmate and where they would present the project. Sofia checks that a question does not become a promise and a possibility does not become a settled decision. They distinguish direct voice and reported speech.'],
[['riassunto','summary'],['promessa','promise'],['decisione','decision'],['intervista','interview']],
[['Report the yes/no question Lavorate?','Ha chiesto se lavoravamo.','Ha chiesto che lavoravamo.','Ha chiesto dove lavoravamo.','Se introduces the indirect yes/no question.'],['Which reports a request?','Ci ha chiesto di aspettare.','Ha detto che aspettiamo is always the same act','Ha chiesto se aspettavamo always means an order','Di + infinitive expresses the addressed request here.'],['What does Sofia check?','That the summary preserves the type and certainty of each statement','Only punctuation','That every question becomes a promise','She checks questions, promises, possibilities, and decisions remain distinct.']],
'Report an interview using one statement, one yes/no question, one information question, and one request.',
[T('Speech to report',['Direct act','Reported model'],[['«Studio qui.»','Ha detto che studiava lì.'],['«Partirò.»','Ha detto che sarebbe partita.'],['«Lavorate?»','Ha chiesto se lavoravamo.'],['«Dove studiate?»','Ha chiesto dove studiavamo.'],['«Aspettate.»','Ci ha chiesto di aspettare.']])]);
L('Superlatives, adverbs, and evaluation','Distinguish better from well and qualify a judgment.',
'An adjective modifies a noun; an adverb describes an action or quality. Buono → migliore compares goodness, while bene → meglio compares how well something happens. Un servizio migliore differs from funziona meglio. Adverbs often use feminine adjective stem + mente: chiara → chiaramente; adjectives in -le/-re often drop e: facilmente.\n\nThe relative superlative uses an article with più/meno: il servizio più utile. An absolute superlative such as utilissimo expresses a high degree, not necessarily first place in a comparison group. Specify the criterion when evaluating: cheaper, easier to access, or more useful for whom? A strong adjective is not a substitute for an explicit standard.',
['Il servizio funziona meglio.','The service works better.','Meglio compares the functioning, not a noun’s adjective.'],['È il servizio più utile per questo gruppo.','It is the most useful service for this group.','The comparison has an explicit reference group.'],
['Gli amici confrontano due luoghi di studio a Genova. Luca preferisce quello più silenzioso; la studentessa sceglie quello più vicino al lavoro. Sofia capisce che “migliore” cambia con il criterio. Giulia scrive chiaramente le due prospettive e rifiuta di trasformarle in una classifica universale. Una descrizione utile deve dire non solo quanto un luogo sembri buono, ma quali esigenze soddisfi e per chi.','The friends compare two Genoa study spaces. Luca prefers the quieter one; the student chooses the one closer to work. Sofia sees that “better” depends on the criterion. Giulia records both perspectives clearly rather than making a universal ranking. A useful description states which needs a place meets and for whom.'],
[['migliore','better (adjective)'],['meglio','better (adverb)'],['esigenza','need / requirement'],['criterio','criterion']],
[['Choose the adverb in works better.','meglio','migliore','migliori','Meglio modifies how the service functions.'],['Does utilissimo necessarily mean ranked first?','No, it expresses a very high degree.','Yes, in every case','Only with a plural noun','The absolute superlative differs from a relative ranking.'],['Why do the preferred study spaces differ?','The speakers use different criteria.','One speaker cannot read.','There is no space near work.','Silence and proximity to work serve different needs.']],
'Compare two places using explicit criteria. Include migliore, meglio, a -mente adverb, and a relative superlative.',
[T('Evaluation forms',['Base','Comparative','Example'],[['buono — good','migliore','un servizio migliore'],['bene — well','meglio','funziona meglio'],['cattivo — bad','peggiore','un risultato peggiore'],['male — badly','peggio','funziona peggio'],['utile','più utile / utilissimo','relative comparison / high degree']]),T('Adverbs',['Adjective','Adverb'],[['chiaro → chiara','chiaramente'],['lento → lenta','lentamente'],['facile','facilmente'],['regolare','regolarmente']])]);
L('Pronouns with non-finite verbs','Manage clitics across modals, gerunds, and instructions.',
'Clitics attach to infinitives and gerunds: leggerlo, parlargli, ascoltandola. A modal often allows two placements: lo posso leggere / posso leggerlo. With a gerund in a progressive, lo sto leggendo / sto leggendolo are possible. Keep the whole cluster together when two pronouns combine.\n\nPositive familiar commands attach the cluster: dammelo, mostracelo. Some short imperatives double the first attached consonant, as in dimmi; combinations with gli have their own spelling patterns. Polite commands place pronouns before the verb: me lo dia. A clear rewrite with nouns is better than a pronoun chain whose referents are lost.',
['Posso mostrartelo.','I can show it to you.','The combined cluster attaches to the infinitive.'],['Me lo può mostrare?','Can you show it to me?','Clitics before the modal are possible in polite address.'],
['La studentessa chiede di vedere la pagina del quaderno. Giulia risponde: «Posso mostrartela, ma alcune immagini non possiamo condividerle». Luca vuole mandarle un file; Sofia suggerisce di spiegarle prima come verrà usato. Mentre lo preparano, si accorgono che un nome non è stato verificato. Decidono di correggerlo invece di chiedere alla lettrice di ricostruire da sola ciò che una catena di pronomi aveva reso poco chiaro.','The student asks to see the notebook page. Giulia can show it but cannot share some images. Luca wants to send a file; Sofia suggests explaining its use first. They notice an unverified name and correct it rather than asking the reader to reconstruct a reference obscured by a pronoun chain.'],
[['file','file'],['correggere','to correct'],['verificare','to verify'],['lettrice','female reader']],
[['Which keeps the combined pronouns together?','Posso mostrartelo.','Posso ti mostrarlo is the model','Posso mostrar te lo.','The cluster te lo attaches as -telo.'],['Choose a polite command.','Me lo dia.','Dammelo!','Me lo dai? as the imperative form','Lei command dia places the clitics before the verb.'],['What do they correct?','An unverified name','The train schedule','A museum price','Un nome non è stato verificato.']],
'Explain a file-sharing process with clear pronouns, then rewrite it with nouns to verify every reference.',
[T('Clitic positions',['Construction','Before finite verb','Attached form'],[['Modal + infinitive','Lo posso leggere.','Posso leggerlo.'],['Progressive','Lo sto leggendo.','Sto leggendolo.'],['Combined modal','Te lo posso mostrare.','Posso mostrartelo.'],['Command','Me lo dia. (polite)','Dammelo! (familiar)']])]);
L('Connectors and structured argument','Link a claim to reasons, evidence, concession, and conclusion.',
'Choose connectors by logical role. Perché/poiché introduces cause; quindi/perciò marks a consequence; tuttavia introduces contrast; sebbene/nonostante commonly introduces a concessive subjunctive clause. A concession recognizes a difficulty without abandoning the main claim: sebbene costi, è utile.\n\nA paragraph needs more than connective words. State a claim, support it with relevant evidence, and explain why the evidence matters. Address a counterpoint fairly before drawing a limited conclusion. Per esempio introduces an example, not automatic proof of a population-wide trend. This structure prepares source-based writing without substituting a template for thinking.',
['Sebbene costi, il servizio è utile.','Although it costs money, the service is useful.','Concession with subjunctive costi.'],['Il tempo è limitato; quindi scegliamo due fonti.','Time is limited; therefore we choose two sources.','Quindi links a consequence to the stated condition.'],
['Giulia propone una tesi: gli spazi di studio dovrebbero essere valutati anche in rapporto agli orari di lavoro. La studentessa offre un esempio concreto, ma Sofia ricorda che una sola esperienza non misura tutti i bisogni. Tuttavia, l’esempio può suggerire una domanda per una ricerca più ampia. Nel quaderno costruiscono un paragrafo con tesi, prova, spiegazione e limite, invece di accumulare aggettivi positivi su un luogo.','Giulia argues that study spaces should also be evaluated against work schedules. The student offers a concrete example, but Sofia notes that one experience cannot measure every need. It can, however, suggest a broader research question. They build a paragraph with claim, evidence, explanation, and limitation instead of piling up positive adjectives.'],
[['tesi','claim / thesis'],['tuttavia','however'],['quindi','therefore'],['bisogno','need']],
[['Which connector signals a consequence?','quindi','sebbene','tuttavia','Quindi means therefore; sebbene concedes and tuttavia contrasts.'],['Which verb fits sebbene il servizio?','costi','costa is always required after sebbene','costare','Sebbene commonly takes subjunctive, giving costi here.'],['What limitation do they note?','One experience cannot measure every need.','No experience can suggest any question.','Only adjectives count as evidence.','Sofia distinguishes one example from a population-wide measurement.']],
'Defend a proposal with a claim, one supported reason, a counterpoint, and a limited conclusion.',
[T('Argument functions',['Role','Useful language','Question to ask'],[['Claim','sostengo che…','What am I arguing?'],['Evidence','secondo la fonte…','What supports it?'],['Explanation','questo suggerisce…','How does it support the claim?'],['Concession','sebbene / tuttavia','What is the strongest limitation?'],['Conclusion','perciò / in conclusione','What can I reasonably conclude?']])]);
L('Proposals and public communication','Write a purposeful message with appropriate address and a clear request.',
'A proposal needs audience, purpose, evidence, and a feasible request. Vorremmo proporre softens a group initiative; le chiediamo di… names the requested action. Choose formal or familiar address consistently and keep the subject of each infinitive clear.\n\nUseful subjunctive structures include affinché (so that) and purché (provided that): affinché tutti possano partecipare. Distinguish a purpose from a guaranteed result; a proposal can aim to improve access without proving it will. A clear letter explains the local evidence and invites a response rather than claiming to speak for an entire community.',
['Vorremmo proporre un incontro.','We would like to propose a meeting.','Conditional plural softens the proposal.'],['Scriviamo affinché tutti possano partecipare.','We write so that everyone can participate.','Affinché introduces a purpose with subjunctive.'],
['Prima di lasciare Genova, gli amici preparano una proposta per la studentessa e il gruppo locale. Vorrebbero organizzare un incontro per discutere gli orari degli spazi di studio. Non promettono una soluzione: offrono le domande raccolte e chiedono quali prospettive manchino. La studentessa suggerisce di coinvolgere chi non ha potuto partecipare all’intervista. Gli amici portano questa osservazione a Trieste: anche una ricerca ben intenzionata lascia fuori qualcuno.','Before leaving Genoa, the friends propose a discussion about study-space hours. They do not promise a solution: they offer their questions and ask which perspectives are missing. The student suggests involving people unable to attend the interview. They take the point to Trieste: even well-intentioned research leaves someone out.'],
[['proposta','proposal'],['coinvolgere','to involve'],['accesso','access'],['prospettiva','perspective']],
[['Which conjunction expresses purpose with the subjunctive?','affinché','quindi','ma','Affinché means so that.'],['What should a useful proposal make clear?','Audience, evidence, purpose, and request','Only flattering adjectives','A guaranteed national solution','A specific proposal states who it addresses and what action it requests.'],['Whom does the student suggest involving?','Those unable to join the interview','Only the photographer','Only museum staff','Chi non ha potuto partecipare all’intervista.']],
'Write and read aloud a short proposal with a defined audience, local evidence, and one feasible request.',
[T('Proposal structure',['Section','Italian scaffold','Purpose'],[['Opening','Gentili responsabili,','Name the audience'],['Aim','Vorremmo proporre…','State the initiative'],['Evidence','Dalle testimonianze raccolte…','Attribute local support'],['Request','Vi chiediamo di…','Name the action'],['Purpose','affinché… possano…','Express intended benefit'],['Closing','Restiamo disponibili…','Invite a response']])]);
// Chapter 10 — AP Global Contexts, Trieste → Roma
L('Mixed-time conditions','Keep a past condition and a present consequence on distinct timelines.',
'A past counterfactual uses se + trapassato subjunctive. Its result need not also be past: se avessi studiato, ora capirei. The earlier imagined study affects present understanding. Conversely, a present condition can frame another time relationship when meaning supports it.\n\nDo not mechanically match two compound tenses. Mark each event on a timeline, then choose its form. Ora makes a present result explicit; allora can locate a past consequence. In a discussion of environmental or social choices, conditional grammar describes a scenario, not a scientifically verified causal model. Evidence must justify the claimed link.',
['Se avessi studiato, ora capirei.','If I had studied, I would understand now.','Past unreal cause, present hypothetical result.'],['Se avessimo più dati, potremmo confrontare i casi.','If we had more data, we could compare the cases.','The condition and consequence concern the present research situation.'],
['A Trieste, Sofia rilegge il percorso dalla prima pagina. Se avessero chiesto subito le stesse domande a tutti, ora avrebbero un confronto più ordinato, ma forse meno aperto alle sorprese. Giulia distingue un limite del metodo da un errore da nascondere. Luca osserva che una ricerca sui luoghi deve lasciare spazio a ciò che non aveva previsto. Decidono di descrivere anche le scelte che hanno cambiato durante il viaggio.','In Trieste, Sofia reviews the whole route. Asking everyone identical questions would now produce a tidier comparison, but perhaps less openness to surprise. Giulia distinguishes a methodological limitation from an error to conceal. Luca says research must leave room for unexpected findings. They decide to describe the choices they changed along the way.'],
[['sorpresa','surprise'],['prevedere','to foresee'],['nascondere','to hide'],['percorso','route / process']],
[['What time does capirei concern in se avessi studiato, ora capirei?','The present result','Only a completed past result','Only the distant future','Ora explicitly locates the hypothetical result now.'],['Does an if-sentence itself prove causation?','No','Always','Only in Italian','Grammar frames a scenario; evidence must support its causal claim.'],['What do they decide to disclose?','Choices they changed during the trip','Only their first plan','No methodological limitations','Le scelte che hanno cambiato durante il viaggio.']],
'Explain one past research choice and an imagined present consequence without claiming more than the evidence supports.',
[T('Mixed-time timeline',['Condition','Result','Timeline'],[['Se avessi studiato,','ora capirei.','Past → present'],['Se avessi saputo,','sarei venuto.','Past → past'],['Se avessimo più dati,','potremmo confrontarli.','Present → present']])]);
L('Advanced reference and qualification','Use chi, ciò che, il quale, and limit scope precisely.',
'Chi can mean the person who or whoever: chi partecipa può parlare. Ciò che means what/that which: ciò che sappiamo. After prepositions, il quale agrees with the antecedent: le persone con le quali parliamo. These forms help clarify reference when che alone would be ambiguous.\n\nScope words matter: alcuni, la maggior parte, in questo campione, per quanto riguarda. Distinguish most participants from most residents, and a source’s description from your inference. Use a possessive relative precisely: le persone le cui voci ascoltiamo. The article agrees with the possessed voci, not directly with the people who own them.',
['Ciò che sappiamo è limitato.','What we know is limited.','Ciò che turns the known content into a noun-like clause.'],['Le persone le cui voci ascoltiamo.','The people whose voices we hear.','Le agrees with feminine plural voci.'],
['Gli amici incontrano un gruppo che discute l’uso degli spazi vicino al mare. Chi partecipa all’incontro non rappresenta automaticamente tutti i residenti. Sofia annota ciò che viene detto, mentre Giulia distingue le persone con le quali hanno parlato da quelle di cui hanno soltanto sentito parlare. Luca propone una frase: “Le voci che abbiamo raccolto mostrano alcune prospettive”. Non è una rinuncia: è una descrizione più onesta della portata del quaderno.','The friends meet a group discussing seaside public space. Attendees do not automatically represent all residents. Sofia records what is said; Giulia distinguishes people they interviewed from those only mentioned. Luca writes that the collected voices show some perspectives. This is not surrender but a more honest account of the notebook’s scope.'],
[['maggior parte','majority / most'],['residente','resident'],['onesto','honest'],['rinuncia','giving up']],
[['Which article fits le persone ___ cui voci?','le','i','il','The article agrees with feminine plural voci.'],['What does ciò che mean?','what / that which','only a person','always where','Ciò che introduces a content-like relative clause.'],['Do meeting participants automatically represent all residents?','No','Yes','Only if they speak loudly','The passage explicitly rejects automatic representativeness.']],
'Summarize a local discussion with clear relative references and two explicit limits on the scope of your claim.',
[T('Reference and scope',['Form','Example','Function'],[['chi','Chi partecipa può parlare.','Whoever / the person who'],['ciò che','Ciò che sappiamo…','What / that which'],['agreeing relative','le persone con le quali…','Clear prepositional reference'],['possessive cui','le persone le cui voci…','Article agrees with possessed noun'],['scope','in questo campione','Limits the claim']])]);
L('Interpreting audio and visual evidence','Identify purpose, viewpoint, and support across modes.',
'An interpretive task asks what a source communicates and how evidence supports that reading. In audio, distinguish the speaker’s claim from another person’s words being quoted. Listen for stance markers: secondo, tuttavia, forse, in conclusione. A transcript can help review, but reading one is not identical to understanding audio unaided.\n\nA graph needs title, axes, units, measured group, date, and source. A photograph has framing and context, not just visible objects. Integrate what the source actually establishes before offering a cultural explanation. When a word is unclear, use surrounding meaning and verify later rather than confidently inventing the missing detail.',
['Secondo la relatrice, il dato è provvisorio.','According to the speaker, the figure is provisional.','Attribution and uncertainty are both explicit.'],['Tuttavia, il grafico non spiega la causa.','However, the chart does not explain the cause.','Contrast marks a limit of the evidence.'],
['A Trieste, gli amici ascoltano una discussione pubblica sulla mobilità. Giulia riconosce una citazione dentro l’intervento e la separa dalla posizione della relatrice. Sofia controlla il titolo di un grafico, ma non trova il periodo di raccolta dei dati. Luca osserva la fotografia che accompagna il materiale: mostra una strada vuota, non dimostra che tutte le strade siano vuote. Nel quaderno indicano ciò che comprendono e ciò che devono ancora verificare.','In Trieste they hear a public mobility discussion. Giulia separates a quotation from the speaker’s position. Sofia finds the chart title but not the data period. Luca notes that a photo of one empty street does not prove all streets are empty. They record what they understand and what still needs verification.'],
[['relatrice','female speaker / presenter'],['provvisorio','provisional'],['grafico','chart'],['mobilità','mobility']],
[['What should you distinguish in a talk with quotations?','The quoted view from the speaker’s own position','Only loud and quiet sounds','Every quote as the speaker’s endorsement','Attribution prevents treating a reported view as an endorsed one.'],['Which missing chart detail limits interpretation?','The period when data were collected','A decorative border','The presenter’s favorite color','Time period is important to interpreting a measured pattern.'],['What does the street photo establish?','That the photographed street appears empty at that moment','That all city streets are always empty','That nobody lives in the city','Framing and moment limit a photograph’s evidentiary scope.']],
'Listen to an external Italian source from the AP practice page. Summarize its aim, cite two details, and identify one uncertainty.',
[T('Interpretive checklist',['Mode','Identify','Avoid'],[['Audio','Speaker, purpose, viewpoint, quoted voices','Treating every quotation as endorsement'],['Text','Main claim, audience, support, limitations','Replacing evidence with a vague topic label'],['Chart','Axes, units, group, period, source','Inferring cause from correlation alone'],['Photo','Frame, moment, caption, provenance','Generalizing beyond what is visible']])]);
L('Source-based argumentative writing','Build a claim that uses sources as evidence, not decoration.',
'A source-based argument needs a clear position, relevant evidence, and an explanation linking evidence to the claim. Paraphrase a source faithfully and attribute it: secondo la fonte A. A quotation without interpretation does not show why the source matters. Compare points of agreement and tension rather than listing summaries independently.\n\nAn effective counterargument is the strongest relevant objection, not a caricature. Concede what it establishes, then explain whether your claim should be narrowed or defended. Use your own Italian and actual sources you have read or heard. The practice task is original study material, not an official exam prompt or an automatically scored AP essay.',
['La fonte A sostiene che l’accesso debba migliorare.','Source A argues that access should improve.','Attribution preserves the source’s position.'],['Questo esempio sostiene la tesi, ma non la dimostra da solo.','This example supports the claim but does not prove it alone.','Evidence is interpreted with an explicit limitation.'],
['Sulla via del ritorno, gli amici provano a scrivere una tesi sul rapporto tra visite e vita quotidiana dei residenti. Le interviste mostrano esperienze diverse; un rapporto potrebbe offrire un quadro più ampio, se letto con attenzione al campione. Giulia rifiuta di usare il quaderno come se fosse un’indagine nazionale. Sofia propone una conclusione limitata e Luca cerca l’obiezione più forte. Il testo diventa un dialogo tra fonti, non una gara a chi usa più citazioni.','On the return journey they draft a claim about visitors and residents’ everyday lives. Interviews show varied experiences; a report might broaden the picture if its sample is understood. Giulia refuses to treat the notebook as a national survey. Sofia proposes a limited conclusion, and Luca seeks the strongest objection. The argument becomes a dialogue among sources, not a quotation contest.'],
[['obiezione','objection'],['sostenere','to support / argue'],['indagine','survey / investigation'],['conclusione','conclusion']],
[['What must follow relevant source evidence?','An explanation of how it supports the claim','Only another quotation','A claim that the source represents everyone','Reasoning makes the evidentiary link explicit.'],['Which is a fair counterargument?','The strongest relevant objection','An intentionally absurd opposing view','No opposing view can matter','A meaningful argument addresses a genuine objection.'],['Why not call the notebook a national survey?','It does not have that evidentiary scope.','It contains Italian words.','It has photographs.','The text explicitly limits the notebook’s representativeness.']],
'Use the AP practice workspace to draft an original argument with attributed sources, a counterpoint, and a limited conclusion.',
[T('Source-to-claim chain',['Step','Italian scaffold','Check'],[['Attribute','Secondo la fonte…','Is the paraphrase accurate?'],['Select','L’esempio mostra…','Is it relevant?'],['Reason','Questo sostiene la tesi perché…','Is the connection explained?'],['Challenge','Un’obiezione è…','Is it the strongest fair objection?'],['Conclude','Entro questi limiti…','Does the scope fit the evidence?']])]);
L('Research presentation','Organize a cultural inquiry around products, practices, and perspectives.',
'A research presentation needs a question, selected evidence, cultural reasoning, and a conclusion. A product can be a song, recording, venue, or artifact; a practice is something people do with or around it; a perspective concerns meanings and values supported by evidence. The categories interact but are not interchangeable labels.\n\nSignpost orally: la domanda che ho esplorato, una fonte importante, questo suggerisce, un limite della ricerca. Speak from notes rather than reading an essay aloud. For AP preparation, use the current official project packet when released; this site offers independent rehearsals and a source notebook, not a substitute submission or official scoring.',
['La domanda che ho esplorato riguarda la musica e la memoria.','The question I explored concerns music and memory.','A clear opening names the inquiry.'],['Questa fonte collega un prodotto a una pratica.','This source connects a product to a practice.','Explain the relationship instead of merely naming categories.'],
['A Roma, gli amici riascoltano il materiale di Milano e preparano una breve presentazione. Giulia apre con una domanda sulla voce e la memoria. Luca sceglie una registrazione come prodotto, ma Sofia gli chiede di spiegare la pratica in cui veniva ascoltata. Le prospettive emergono dalle testimonianze, non dai loro gusti personali. Nel quaderno restano anche le fonti scartate e le ragioni della scelta. Presentare bene significa rendere comprensibile il percorso, non fingere di aver trovato una risposta totale.','Back in Rome they revisit the Milan material and prepare a short presentation. Giulia opens with voice and memory. Luca selects a recording as a product, while Sofia asks about the listening practice around it. Perspectives emerge from accounts, not personal taste. They retain rejected sources and selection reasons. A good presentation makes the inquiry understandable without pretending its answer is total.'],
[['ricerca','research'],['prodotto','product'],['pratica','practice'],['scartare','to discard']],
[['Which is a practice rather than simply a product?','Listening to a recording at a community event','The recording file by itself','The venue name alone','A practice is an activity or patterned use in context.'],['What should support a claim about a cultural perspective?','Relevant source evidence and reasoning','Only personal taste','A national stereotype','Perspectives should be inferred carefully from evidence.'],['What do the friends retain besides selected sources?','Rejected sources and reasons for selection','Only a finished script','No research notes','They keep fonti scartate and selection reasons.']],
'Prepare a three-minute presentation in the AP practice page using your own research question and notes.',
[T('Presentation map',['Part','Italian signpost','Evidence task'],[['Question','La domanda che ho esplorato…','Define scope'],['Material','Ho scelto questa fonte perché…','Explain selection'],['Connection','Il prodotto si collega alla pratica…','Show cultural relationship'],['Perspective','La testimonianza suggerisce…','Support interpretation'],['Limit','Un limite della ricerca è…','Bound the conclusion']])]);
L('Research Q&A and final synthesis','Respond directly, use evidence, and acknowledge the limits of your answer.',
'An effective spoken answer responds to the actual question, adds specific support, and explains the connection. Se ho capito bene can clarify an ambiguous prompt; non ho dati sufficienti acknowledges a real limit. Avoid reciting a memorized paragraph that ignores what was asked.\n\nUse tense and mood to distinguish what you did, what a source says, and what you would do next: ho confrontato, la fonte sostiene, approfondirei. A short answer can be well developed without being exhaustive. The AP practice page offers four forty-second response rehearsals; use the official current packet for actual project requirements and keep your own research and language work central.',
['Ho confrontato due fonti; approfondirei la seconda.','I compared two sources; I would investigate the second further.','Past work and a hypothetical next step use different forms.'],['Non ho dati sufficienti per generalizzare.','I do not have enough data to generalize.','A precise limitation is better than an unsupported universal answer.'],
['Luca domanda quale fonte abbia cambiato di più la loro idea iniziale. Giulia sceglie l’intervista in cui una parola aveva assunto un significato nuovo durante la discussione. Sofia chiede cosa farebbero con più tempo: ascolterebbero persone rimaste fuori dal percorso. Il quaderno comincia a Roma con pochi nomi e finisce nello stesso luogo con domande più precise. Gli amici non hanno imparato a parlare per tutti. Hanno imparato a descrivere, chiedere, confrontare e spiegare perché una voce merita di essere ascoltata nel suo contesto.','Luca asks which source most changed their initial idea. Giulia chooses the interview where a word gained new meaning during discussion. With more time, they would listen to people left outside the route. The notebook begins in Rome with a few names and ends there with better questions. They have learned not to speak for everyone, but to describe, ask, compare, and explain why a voice deserves attention in its context.'],
[['approfondire','to investigate further'],['sufficiente','sufficient'],['sintesi','synthesis'],['contesto','context']],
[['Which form describes a hypothetical next step?','approfondirei','ho confrontato','la fonte sostiene','Approfondirei is conditional: I would investigate further.'],['What is the best response to an unsupported generalization?','State the evidence’s actual limit.','Invent a statistic.','Ignore the question.','Acknowledging limits keeps the answer accurate and responsive.'],['Whom would they hear with more time?','People left out of their route','Only the same three travelers','Only celebrities','Ascolterebbero persone rimaste fuori dal percorso.']],
'Answer four research questions in forty seconds each. Respond, support, connect, and state a limitation where needed.',
[T('Q&A answer structure',['Move','Italian model','Purpose'],[['Respond','La fonte più utile è stata…','Answer the actual question'],['Support','In particolare, mostra…','Name a specific detail'],['Connect','Questo ha cambiato la mia idea perché…','Explain significance'],['Limit / next step','Per verificarlo meglio, approfondirei…','Acknowledge scope and future inquiry']])]);
